-- BCV: import the supplied place dataset into the EXISTING 25-table public schema.
-- Run db/001_schema.sql and db/002_seed_reference.sql first.
-- This file creates no table/column and refuses to overwrite existing import targets.
-- Source VN-XXXX becomes place_id XXXX; SRC_REGION_N becomes region_id N.
-- Secondary place types are preserved as kind__* values in place_feature_value
-- (345 positive kind labels match all 345 source place_type_link rows).
-- Source-only URLs, source hashes, aliases, model artifact metadata, feature order/
-- group scaling, distance_scale and stride_length_m have no columns in this schema.
-- They remain in the supplied source file and are not written to the database.
-- Source coordinates are rounded by NUMERIC(9,6); NULL rating_count becomes 0.

BEGIN;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL search_path = public;

DO $check$
BEGIN
    IF (SELECT count(*) FROM pg_catalog.pg_tables
        WHERE schemaname = 'public' AND tablename <> 'spatial_ref_sys') <> 25 THEN
        RAISE EXCEPTION 'Expected exactly 25 application tables in public';
    END IF;
    IF (SELECT count(*) FROM public.place_type
        WHERE name = ANY (ARRAY['Bảo tàng', 'Chợ', 'Công trình và không gian xây dựng', 'Cảnh quan nông nghiệp', 'Di tích lịch sử', 'Khu vui chơi và nghỉ dưỡng', 'Làng nghề và thủ công', 'Làng, bản và phố cổ', 'Thiên nhiên', 'Tôn giáo và tín ngưỡng'])) <> 10 THEN
        RAISE EXCEPTION 'The 10 place types from 002_seed_reference.sql are required';
    END IF;
    IF (SELECT count(*) FROM public.recommendation_criterion
        WHERE code = ANY (ARRAY['ACTIVITY', 'CLUSTER', 'POPULARITY', 'PREFERENCE', 'RATING', 'ecosystem__flooded_habitat', 'ecosystem__forest', 'ecosystem__grassland', 'kind__agriculture', 'kind__community', 'kind__craft', 'kind__heritage', 'kind__market', 'kind__museum', 'kind__nature', 'kind__recreation', 'kind__religious', 'kind__structure', 'landform__cave', 'landform__coast', 'landform__dunes', 'landform__island', 'landform__lagoon', 'landform__lake', 'landform__mountain', 'landform__river', 'landform__stream', 'landform__valley', 'landform__waterfall', 'theme__agriculture', 'theme__architecture', 'theme__craft', 'theme__cuisine', 'theme__culture', 'theme__ecology', 'theme__games', 'theme__geology', 'theme__history', 'theme__relaxation', 'theme__spirituality'])) <> 40 THEN
        RAISE EXCEPTION 'The 40 criteria from 002_seed_reference.sql are required';
    END IF;
    IF (SELECT count(*) FROM public.region) <> 0
       OR (SELECT count(*) FROM public.place) <> 0
       OR (SELECT count(*) FROM public.recommendation_config) <> 0
       OR (SELECT count(*) FROM public.recommendation_weight) <> 0
       OR (SELECT count(*) FROM public.place_feature) <> 0
       OR (SELECT count(*) FROM public.place_feature_value) <> 0 THEN
        RAISE EXCEPTION 'Import targets must be empty; existing rows were left unchanged';
    END IF;
END
$check$;

