INSERT INTO public.place
    (place_id, region_id, place_type_id, name, latitude, longitude,
     introduction, rating, rating_count, status)
SELECT v.place_id, v.region_id, t.place_type_id, v.name, v.latitude, v.longitude,
       v.introduction, v.rating, v.rating_count, 'DRAFT'
FROM (VALUES
    (1, 25, 'Thiên nhiên', 'Bãi Dài Cam Ranh', 12.0500128, 109.2082756, 'Bãi biển hoang sơ với vẻ đẹp tự nhiên, lý tưởng để thư giãn và tắm biển', 4.5, 845),
    (2, 25, 'Di tích lịch sử', 'Tháp Bà Ponagar', 12.26527778, 109.19555556, 'Công trình kiến trúc Chăm cổ, nơi du khách có thể tìm hiểu về lịch sử và văn hóa Chăm', 4.5, 32654),
    (3, 25, 'Di tích lịch sử', 'Thành cổ Diên Khánh', 12.2548202, 109.0887246, 'Di tích lịch sử với kiến trúc thành cổ độc đáo, được xây dựng từ thời Nguyễn.', NULL, 0),
    (4, 25, 'Khu vui chơi và nghỉ dưỡng', 'VinWonders Nha Trang', 12.2173958, 109.2412179, 'Công viên giải trí trên đảo Hòn Tre, nổi bật với nhiều trò chơi và hoạt động hấp dẫn.', 4.7, 20880),
    (5, 25, 'Thiên nhiên', 'Suối Ba Hồ', 12.3914277, 109.13891269999999, 'Gồm ba hồ nước trong xanh nằm trên núi, thích hợp cho trekking và tắm suối', 4.5, 279),
    (6, 26, 'Thiên nhiên', 'Đảo Phú Quốc', 10.21608143, 103.95939055, 'Là điểm du lịch nổi tiếng nhất Kiên Giang, được mệnh danh là "Đảo Ngọc" với nhiều bãi biển đẹp và dịch vụ cao cấp', 4.4, 6319),
    (7, 26, 'Thiên nhiên', 'Biển Mũi Nai', 10.380867, 104.4453374, 'Bãi biển hiền hòa, nơi lý tưởng để thư giãn và ngắm cảnh hoàng hôn', 4, 3687),
    (8, 26, 'Tôn giáo và tín ngưỡng', 'Chùa Láng Cát', 9.999427299999999, 105.0944866, 'Ngôi chùa cổ kính mang đậm dấu ấn Phật giáo.', 4.3, 105),
    (9, 26, 'Thiên nhiên', 'Vườn quốc gia U Minh Thượng', 9.58333, 105.083, 'Rừng ngập mặn với hệ sinh thái phong phú, là nơi lý tưởng để khám phá thiên nhiên hoang dã và tham quan bằng thuyền', 4.3, 16),
    (10, 26, 'Di tích lịch sử', 'Mộ chị Sứ', 10.106083, 104.8939744, 'Khu di tích lịch sử nổi tiếng, gắn liền với cuộc kháng chiến chống Pháp.', 4.4, 1004),
    (11, 27, 'Tôn giáo và tín ngưỡng', 'Nhà Thờ Gỗ Kon Tum', 14.345037, 108.013158, 'Một biểu tượng của Kon Tum mang kiến trúc độc đáo pha trộn giữa phong cách Roman và nét văn hóa Tây Nguyên', 4.7, 4300),
    (12, 27, 'Công trình và không gian xây dựng', 'Cầu Treo Kon Klor', 14.3469891, 108.0355259, 'Cây cầu treo lớn và đẹp nhất ở Kon Tum, bắc qua sông Đăk Bla, được bao quanh bởi những cánh đồng lúa và núi rừng xanh mát', 4.7, 32),
    (13, 27, 'Thiên nhiên', 'Vườn Quốc Gia Chư Mom Ray', 14.46666667, 107.63333333, 'Là khu bảo tồn thiên nhiên lớn nhất Việt Nam, nổi bật với hệ sinh thái phong phú, những cánh rừng nguyên sinh và động vật quý hiếm', 4.7, 90),
    (14, 27, 'Thiên nhiên', 'Đỉnh Ngọc Linh', 15.08754057, 107.92636925, 'Ngọn núi cao nhất ở Tây Nguyên, thuộc dãy Trường Sơn, là nơi sinh sống của nhiều loài động thực vật quý hiếm.', NULL, 0),
    (15, 27, 'Thiên nhiên', 'Thác Đăk Sing', 14.6972288, 107.8690702, 'Thác Đăk Sing tại khu vực Kon Đào, Đắk Tô, Kon Tum theo địa giới gốc của dataset. Đây là điểm thác tự nhiên được chọn để thay tên chung Thác Đắk Tô chưa xác định được địa điểm cụ thể.', 4.5, 14),
    (16, 28, 'Thiên nhiên', 'Đèo Ô Quy Hồ', 22.3532, 103.76453, 'Một trong "Tứ đại đỉnh đèo" của Tây Bắc, Đèo Ô Quy Hồ nối liền Lào Cai và Lai Châu, nổi tiếng với cảnh sắc tuyệt đẹp và độ cao hùng vĩ', 4.7, 789),
    (17, 28, 'Thiên nhiên', 'Đỉnh Pu Ta Leng', 22.422778, 103.603333, 'Đỉnh núi cao thứ hai Việt Nam (3.049m), thuộc dãy Hoàng Liên Sơn, được mệnh danh là "nóc nhà thứ hai" của Đông Dương.', 4.9, 9),
    (18, 28, 'Cảnh quan nông nghiệp', 'Cánh đồng Mường Than', 21.9881624, 103.9128124, 'Vào mùa lúa chín, cánh đồng Mường Than rực rỡ sắc vàng, tạo nên một bức tranh thiên nhiên thơ mộng', 4.8, 56),
    (19, 28, 'Thiên nhiên', 'Hồ Thủy Điện Lai Châu', 22.13944444, 102.98527778, 'Hồ nước nhân tạo khổng lồ được tạo nên từ công trình Thủy điện Lai Châu, nằm giữa khung cảnh núi non thơ mộng.', NULL, 0),
    (20, 28, 'Chợ', 'Chợ phiên Sìn Hồ', 22.3596522, 103.2491335, 'Nơi diễn ra các hoạt động mua bán nhộn nhịp của các dân tộc Thái, H’Mông, Dao, Lự...', 4.4, 42),
    (21, 31, 'Thiên nhiên', 'Hồ Xuân Hương', 11.941845, 108.446835, 'Biểu tượng của Đà Lạt, hồ nằm ngay trung tâm thành phố, bao quanh bởi rừng thông và những vườn hoa.', 4.7, 407),
    (22, 31, 'Tôn giáo và tín ngưỡng', 'Thiền viện Trúc Lâm Đà Lạt', 11.9041575, 108.4347865, 'Một thiền viện nổi tiếng tọa lạc gần Hồ Tuyền Lâm, mang kiến trúc thanh tịnh và không gian yên bình.', 4.6, 3958),
    (23, 31, 'Chợ', 'Chợ Đêm Đà Lạt', 11.9414964, 108.4372724, 'Chợ đêm Đà Lạt là nơi bạn có thể thưởng thức đặc sản như bánh tráng nướng, sữa đậu nành và mua quà lưu niệm.', 4.2, 19220),
    (24, 31, 'Di tích lịch sử', 'Dinh III Bảo Đại (Đà Lạt)', 11.93017222, 108.42966111, 'Một trong ba dinh thự của vua Bảo Đại tại Đà Lạt, mang phong cách kiến trúc Pháp tinh tế.', 4.2, 9671),
    (25, 31, 'Thiên nhiên', 'Thác Voi', 11.82384, 108.336735, 'Tọa lạc ở Nam Ban, thác Voi hùng vĩ và hoang sơ, là nơi lý tưởng cho những ai yêu thích khám phá thiên nhiên.', 4, 141),
    (26, 32, 'Thiên nhiên', 'Động Tam Thanh', 21.8555666, 106.7467985, 'Được mệnh danh là "Đệ nhất bát cảnh Xứ Lạng"các nhũ đá kỳ thú và nhiều di tích cổ như tượng Phật A Di Đà cao 2m được tạc từ thế kỷ 15.', NULL, 0),
    (27, 32, 'Chợ', 'Chợ Đông Kinh', 21.8513451, 106.7612705, 'Là trung tâm thương mại lớn nhất ở Lạng Sơn, nổi tiếng với các mặt hàng phong phú', 3.9, 4070),
    (28, 32, 'Công trình và không gian xây dựng', 'Cửa khẩu Hữu Nghị', 21.97176111, 106.71103889, 'Đây là cửa khẩu quốc tế lớn giữa Việt Nam và Trung Quốc, nằm trên tuyến quốc lộ 1A.', 4.5, 769),
    (29, 32, 'Thiên nhiên', 'Đèo Bông Lau', 22.342784, 106.446721, 'Là một cung đèo đẹp với những khúc cua uốn lượn và khung cảnh thiên nhiên ngoạn mục.', 4.6, 27),
    (30, 32, 'Tôn giáo và tín ngưỡng', 'Chùa Tiên (Lạng Sơn)', 21.8363282, 106.7569654, 'Chùa Tiên nằm trên núi Đại Tượng, gắn liền với nhiều câu chuyện huyền thoại và mang đậm dấu ấn Phật giáo.', 4.4, 329),
    (31, 30, 'Thiên nhiên', 'Đỉnh Núi Fansipan', 22.304276, 103.777063, 'Fansipan được mệnh danh là “Nóc nhà Đông Dương” với độ cao 3.147m.', 4.8, 1763),
    (32, 30, 'Thiên nhiên', 'Cổng Trời Ô Quy Hồ', 22.3527515, 103.7653048, 'Đèo Ô Quy Hồ là một trong "Tứ đại đỉnh đèo" của Tây Bắc, nối liền Lào Cai và Lai Châu.', 4.4, 702),
    (33, 30, 'Chợ', 'Chợ phiên Bắc Hà', 22.5355989, 104.2918025, 'Chợ phiên Bắc Hà nổi tiếng với các mặt hàng thổ cẩm, nông sản và các món ăn đặc trưng của người dân tộc H’Mông, Dao.', 4.8, 44),
    (34, 30, 'Thiên nhiên', 'Thác Tình Yêu', 22.3473362, 103.7724285, 'Là một điểm đến lãng mạn với dòng nước trong xanh chảy qua rừng nguyên sinh.', 4.5, 1206),
    (35, 30, 'Tôn giáo và tín ngưỡng', 'Đền Thượng', 22.5096077, 103.9681621, 'Là nơi thờ Trần Hưng Đạo, vị tướng tài ba trong lịch sử Việt Nam.', 4.7, 867),
    (36, 29, 'Thiên nhiên', 'Làng nổi Tân Lập', 10.7139066, 105.9860873, 'Là khu rừng tràm ngập nước rộng lớn, nổi tiếng với con đường xuyên rừng dài gần 5km.', 4, 2441),
    (37, 29, 'Di tích lịch sử', 'Nhà cổ Trăm Cột', 10.4825, 106.6913889, 'Là một ngôi nhà cổ độc đáo với 120 cột gỗ quý được chạm khắc tinh xảo.', 4.1, 621),
    (38, 29, 'Tôn giáo và tín ngưỡng', 'Chùa Tôn Thạnh', 10.6054291, 106.6462875, 'Ngôi chùa này là nơi cụ Nguyễn Đình Chiểu từng ở và sáng tác bài văn tế "Văn tế nghĩa sĩ Cần Giuộc".', 4.7, 729),
    (39, 29, 'Thiên nhiên', 'Sông Vàm Cỏ', 10.490555555556, 106.72777777778, 'Hai dòng sông lớn chảy qua Long An tạo nên vẻ đẹp sông nước đặc trưng.', NULL, 0),
    (40, 29, 'Chợ', 'Chợ đêm Tân An', 10.5313746, 106.4165997, 'Là nơi lý tưởng để thưởng thức ẩm thực địa phương và mua sắm các đặc sản Long An', 4.4, 108),
    (41, 33, 'Tôn giáo và tín ngưỡng', 'Nhà thờ Phú Nhai', 20.307651, 106.329848, 'Là một trong những nhà thờ lớn và cổ kính nhất Việt Nam, mang phong cách kiến trúc Gothic đặc sắc.', 4.7, 1282),
    (42, 33, 'Tôn giáo và tín ngưỡng', 'Đền Trần', 20.456854, 106.167306, 'Nằm tại phường Lộc Vượng, thành phố Nam Định, đền Trần thờ các vua nhà Trần, gắn liền với lịch sử hào hùng của triều đại này.', 4.7, 1823),
    (43, 33, 'Thiên nhiên', 'Vườn quốc gia Xuân Thủy', 20.23, 106.517, 'Đây là khu bảo tồn thiên nhiên nằm ở huyện Giao Thủy, thuộc vùng hạ lưu sông Hồng.', 4.3, 970),
    (44, 33, 'Chợ', 'Chợ Viềng', 20.336947, 106.1807565, 'Là phiên chợ đặc biệt chỉ diễn ra một lần trong năm vào đêm mùng 7, rạng sáng mùng 8 tháng Giêng âm lịch.', 4.5, 1043),
    (45, 33, 'Thiên nhiên', 'Hồ Vị Xuyên', 20.4310948, 106.1821805, 'Hồ nằm trong thành phố Nam Định, là một địa điểm lý tưởng để thư giãn, đi dạo, thưởng thức không gian xanh và yên bình.', 4.7, 234),
    (46, 34, 'Di tích lịch sử', 'Làng Sen', 18.67986111, 105.552, 'Là một ngôi nhà tranh đơn sơ, giếng Cốc, và những kỷ vật gắn liền với thời thơ ấu của Bác.', 4.6, 8952),
    (47, 34, 'Thiên nhiên', 'Bãi biển Cửa Lò', 18.7784704, 105.7486874, 'Một trong những bãi biển đẹp nhất miền Trung, Cửa Lò thu hút du khách với cát trắng mịn, nước biển trong xanh và hải sản tươi ngon.', 4.3, 1657),
    (48, 34, 'Di tích lịch sử', 'Khu di tích Truông Bồn', 18.7863002, 105.4110678, 'Là một di tích lịch sử quan trọng, nơi tưởng nhớ các anh hùng liệt sĩ đã hy sinh trong cuộc kháng chiến chống Mỹ.', 4.5, 1172),
    (49, 34, 'Cảnh quan nông nghiệp', 'Đồi chè Thanh Chương', 18.731346, 105.281245399999, 'Được mệnh danh là "đảo chè", đồi chè Thanh Chương là địa điểm lý tưởng để chụp ảnh và tận hưởng không khí trong lành.', 4.7, 562),
    (50, 34, 'Thiên nhiên', 'Hang Thẩm Ồm', 19.6502041, 105.0741455, 'Là một hang động lớn, với nhiều thạch nhũ kỳ ảo, hình thù độc đáo.', 4.7, 13),
    (51, 35, 'Thiên nhiên', 'Tràng An', 20.25666667, 105.89638889, 'Là Di sản Văn hóa và Thiên nhiên thế giới, Tràng An nổi bật với cảnh núi non hùng vĩ và hệ thống hang động độc đáo.', 4.6, 15397),
    (52, 35, 'Thiên nhiên', 'Tam Cốc', 20.218515, 105.914698, 'Được mệnh danh là "vịnh Hạ Long trên cạn", với cảnh sắc thiên nhiên tuyệt đẹp của núi đá vôi, cánh đồng lúa, và dòng sông Ngô Đồng.', 4.5, 18465),
    (53, 35, 'Di tích lịch sử', 'Cố đô Hoa Lư', 20.2843154, 105.9083607, 'Là kinh đô của nước Đại Cồ Việt dưới triều Đinh và Tiền Lê, Hoa Lư lưu giữ nhiều di tích lịch sử quan trọng', 4.3, 12531),
    (54, 35, 'Thiên nhiên', 'Vườn quốc gia Cúc Phương', 20.31666667, 105.60833333, 'Là vườn quốc gia đầu tiên của Việt Nam với hệ động thực vật phong phú, những cây cổ thụ nghìn năm tuổi và các hang động tiền sử.', 4.5, 5206),
    (55, 35, 'Thiên nhiên', 'Hồ Đồng Chương', 20.229305555555555, 105.79791666666667, 'Hồ Đồng Chương là một hồ nước tự nhiên nằm giữa rừng thông, rất yên bình và thơ mộng.', 3.9, 315),
    (56, 36, 'Thiên nhiên', 'Vịnh Vĩnh Hy', 11.71666667, 109.20277778, 'Một trong bốn vịnh đẹp nhất Việt Nam, Vĩnh Hy gây ấn tượng bởi nước biển trong xanh, bãi cát trắng mịn, và các rạn san hô rực rỡ.', 4.5, 1395),
    (57, 36, 'Thiên nhiên', 'Vườn quốc gia Núi Chúa', 11.70027778, 109.15277778, 'Là khu bảo tồn thiên nhiên với hệ sinh thái rừng khô hạn độc đáo, được UNESCO công nhận là Khu dự trữ sinh quyển thế giới.', 4.3, 2978),
    (58, 36, 'Di tích lịch sử', 'Tháp Po Klong Garai', 11.601831, 108.9442935, 'Đây là nơi thờ vua Po Klong Garai, thể hiện kiến trúc và nghệ thuật điêu khắc tinh xảo của người Chăm.', 4.8, 28),
    (59, 36, 'Cảnh quan nông nghiệp', 'Vườn nho Thái An Quán', 11.6652688, 109.1724179, 'Vườn nho tại thôn Thái An, xã Vĩnh Hải, khu vực Ninh Thuận, phục vụ tham quan và tìm hiểu hoạt động trồng nho.', 4.8, 46),
    (61, 37, 'Tôn giáo và tín ngưỡng', 'Đền Hùng', 21.3682242, 105.3214424, 'Là khu di tích lịch sử quốc gia đặc biệt, nơi thờ các vua Hùng – những người dựng nước đầu tiên của dân tộc Việt Nam.', 4.7, 6210),
    (62, 37, 'Làng, bản và phố cổ', 'Làng cổ Hùng Lô', 21.3724056999999, 105.3859093, 'Nổi tiếng với các ngôi nhà cổ hàng trăm năm tuổi, cùng các nghề truyền thống như làm bánh chưng, bánh giầy.', NULL, 0),
    (63, 37, 'Khu vui chơi và nghỉ dưỡng', 'Đảo Ngọc Xanh', 21.1659611, 105.2845945, 'Là khu du lịch sinh thái kết hợp nghỉ dưỡng, với cảnh quan thiên nhiên trong lành, công viên nước, trò chơi cảm giác mạnh và khu suối nước nóng', 3.9, 267),
    (64, 37, 'Thiên nhiên', 'Vườn quốc gia Xuân Sơn', 21.15, 104.933, 'Là một trong những khu bảo tồn thiên nhiên lớn nhất miền Bắc, nổi bật với hệ sinh thái rừng nhiệt đới và các loài động, thực vật phong phú', 4.4, 2340),
    (65, 37, 'Thiên nhiên', 'Suối nước nóng Thanh Thủy', 21.1548991, 105.2791803, 'Là khu vực có các dịch vụ nghỉ dưỡng và trị liệu hiện đại.', NULL, 0),
    (66, 38, 'Thiên nhiên', 'Gành Đá Đĩa', 13.354066, 109.293787, 'Một kỳ quan thiên nhiên độc đáo, Gành Đá Đĩa nổi bật với những cột đá bazan xếp chồng lên nhau như những chiếc đĩa.', 4.5, 8296),
    (67, 38, 'Thiên nhiên', 'Hòn Yến', 13.225716, 109.3081206, 'Là một hòn đảo nhỏ với cảnh quan hoang sơ, nổi bật với những rạn san hô tuyệt đẹp.', 4.7, 307),
    (68, 38, 'Công trình và không gian xây dựng', 'Hải đăng Đại Lãnh', 12.8965683, 109.4571386, 'Là điểm cực Đông của Việt Nam, nơi đón ánh bình minh đầu tiên trên đất liền', 4.6, 2406),
    (69, 38, 'Thiên nhiên', 'Suối nước nóng Triêm Đức', 13.3532426, 109.0576572, 'Là một điểm đến thú vị để thư giãn và ngâm mình trong làn nước khoáng ấm áp.', 4.4, 10),
    (70, 38, 'Di tích lịch sử', 'Tháp Nhạn', 13.07777778, 109.29722222, 'Tháp Nhạn nằm trên núi Nhạn ở thành phố Tuy Hòa, là một công trình kiến trúc Chăm cổ kính và linh thiêng.', 4.7, 953),
    (71, 39, 'Thiên nhiên', 'Động Phong Nha', 17.581325, 106.283125, 'Phong Nha - Kẻ Bàng, được UNESCO công nhận là Di sản Thiên nhiên Thế giới.', 4.7, 2960),
    (72, 39, 'Thiên nhiên', 'Bãi Đá Nhảy', 17.6607487, 106.515919599999, 'Là nơi nổi bật với những khối đá có hình thù độc đáo bên bờ biển.', 4.7, 24),
    (73, 39, 'Tôn giáo và tín ngưỡng', 'Đền Thánh Mẫu Liễu Hạnh', 17.9535027, 106.4691482, 'Là nơi linh thiêng thờ vị thánh trong tín ngưỡng dân gian Việt Nam.', 4.8, 119),
    (74, 39, 'Di tích lịch sử', 'Nhà lưu niệm Đại tướng Võ Nguyên Giáp', 17.2437766, 106.7498463, 'Là nơi lưu giữ những kỷ vật gắn bó với tuổi thơ của Đại tướng Võ Nguyên Giáp.', 4.9, 122),
    (75, 39, 'Thiên nhiên', 'Sông Chày', 17.57414, 106.252053899999, 'Là điểm đến lý tưởng cho những người yêu thích phiêu lưu, Sông Chày kết hợp giữa vẻ đẹp sông nước và hang động.', 4.3, 64),
    (76, 40, 'Làng, bản và phố cổ', 'Phố cổ Hội An', 15.88333333, 108.33333333, 'Những ngôi nhà cổ kính và có kiến trúc độc đáo như: những ngôi nhà lợp ngối đá, nhưng bức tường vàng mang lại vẻ đẹp yên bình. Đặt biệt bạn có thể thư dãn dạo bước với những đường nhỏ hẹp quanh sông Hoài', 4.8, 802),
    (77, 40, 'Thiên nhiên', 'Bãi biển An Bàng', 15.9136072, 108.340648899999, 'Sở hữu vẻ đẹp yên bình, hoang sơ với những bãi các vàng, biển xanh, khí hậu vô cùng mát mẻ và trong lành.', 4.3, 20559),
    (78, 40, 'Di tích lịch sử', 'Tháp Chiên Đàn', 15.6158093, 108.442489, 'Hiểu hơn về văn hóa Champa, sở hữu một nhà trưng bày nhưng tác phẩm điêu khắc tiêu biểu, vô vàn những món đồ quý hiếm', 4.4, 163),
    (79, 40, 'Thiên nhiên', 'Đỉnh Quế', 15.8364454, 107.3820824, 'Đỉnh Quế thuộc khu vực Tây Giang, Quảng Nam, nổi bật với cảnh quan núi Trường Sơn và hoạt động ngắm mây. Khu vực xung quanh gắn với đời sống văn hóa của cộng đồng Cơ Tu.', 4.4, 610),
    (80, 40, 'Di tích lịch sử', 'Thánh Địa Mỹ Sơn', 15.76666667, 108.11666667, 'Một thung lũng có đường kính 2km, Nơi đây bao quanh là núi đồi, vô cùng ẩn mình. Địa điểm này từng là nơi tổ chức cúng tế vương triều Champa. Khám quá nhiều di sản quý báu khi đến nới đây.', 4.5, 13044),
    (81, 41, 'Thiên nhiên', 'Núi Thiên Ấn', 15.149357, 108.8181961, 'Là một ngọn núi từ lâu đã rất nổi tiếng với khung cảnh hùng vĩ và mang lại một giá trị lịch sử vô cùng lớn lao, với vẻ đẹp thơ mộng và dịu dàng mà nó mang lại là điểm đặc biệt hu hút khách du lịch hàng năm.', NULL, 0),
    (82, 41, 'Thiên nhiên', 'Bãi biển Mỹ Khê (Quảng Ngãi)', 15.183863888888888, 108.89453333333334, 'Bãi biển Mỹ Khê thuộc khu vực Sơn Tịnh, Quảng Ngãi, có bãi cát dài ven biển và cảnh quan làng chài. Đây là địa danh khác với bãi biển Mỹ Khê tại Đà Nẵng.', 4.5, 565),
    (83, 41, 'Cảnh quan nông nghiệp', 'Đồng muối Sa Huỳnh', 14.6885833, 109.0636823, 'Vựa muối quan trọng nhất miền Trung thân yêu của chúng ta, những bãi muối trắng phao, đến nơi đây bạn sẽ được trãi nghiệm các hoạt động hằng ngày của bà con nơi đây, hứa hẹn sẽ mang lại cho bạn những trãi nghiệm rất khác so với các hoạt động du lịch như lên rừng hay xuống biển.', 4.3, 276),
    (84, 41, 'Thiên nhiên', 'Thác Trắng', 14.9065727, 108.658744099999, 'Khùng cảnh ở đây ấn tượng với rừng núi hoang sơ, trong lành, dòng thác đổ xuống giữa khung cảnh bao quanh là biết bao cây cối sông suối tung bọt trắng xóa', 4.1, 854),
    (85, 41, 'Thiên nhiên', 'Đèo Vi Ô Lắc', 14.762611, 108.520991, 'Nằm cao hơn 1300m so với mực nước biển, sự quanh co uốn lượn của các cung đường cùng với không khí thơ mộng luôn mang đến nhưng vẻ đẹp tuyệt mỹ cùng hàng cỏ xanh tươi mọc hai bên đường khi du khách đi lên đèo là nhưng nét ấn tượng nhất, thú vị nhất', 4.7, 279),
    (86, 42, 'Thiên nhiên', 'Vịnh Hạ Long', 20.9, 107.2, 'Là một trong những di sản thiên nhiên thế giới được UNESCO công nhận. Với diện tích 1553km2, gần 2000 hòn đảo lớn nhỏ, vịnh Hạ Long được thiên nhiên ưu ái có hệ thống hang động và đảo đá vừa đa dạng lại tuyệt đẹp.', 4.6, 8478),
    (87, 42, 'Thiên nhiên', 'Biển Bãi Cháy', 20.9430558, 107.0291412, 'Bãi Cháy luôn thu hút rất nhiều du khách đến tham quan trải nghiệm và tắm biển. Bãi biển cùng đã có thêm những hoạt động thể thao trên biển như cano, dù bay hay nhà phao để du khách có thể tận hưởng những dịch vụ cao cấp hơn.', 4.3, 2332),
    (88, 42, 'Khu vui chơi và nghỉ dưỡng', 'Sun World Hạ Long', 20.953975399999997, 107.0501218, 'Du lịch Hạ Long thì chắc chắn không nên bỏ qua Sun World Halong Park - khu phức hợp giải trí nổi tiếng dành cho mọi lứa tuổi. Nếu bạn đã từng đến VinWonders thì công viên Hạ Long cũng là một thiên đường tương tự như vậy, nhưng sẽ náo nhiệt hơn nhiều nhé.', 4.4, 3995),
    (89, 42, 'Làng, bản và phố cổ', 'Làng chài Cửa Vạn', 20.8072422, 107.1179445, 'Không chỉ được tận hưởng không gian yên tĩnh, thanh bình nơi đây, du khách còn có thêm những hiểu biết về đời sống văn hóa, thường nhật của các ngư dân. Ngư dân ở đây hết sức thân thiện và mến khách. Hành khách có thể chèo thuyền thúng, cắt cá, câu mực… để hiểu hơn cuộc sống dân chài.', 4.8, 9),
    (90, 42, 'Thiên nhiên', 'Động Thiên Cung (Hạ Long)', 20.8733, 107.075, 'Hang động trong khu vực vịnh Hạ Long, Quảng Ninh, có nhiều khối thạch nhũ và không gian hang đá vôi. Địa danh khác với động Thiên Cung tại Suối Giàng.', NULL, 0),
    (91, 43, 'Di tích lịch sử', 'Nghĩa trang Liệt sĩ Quốc gia Trường Sơn', 16.958621, 106.95485883, 'Địa điểm ghi dấu ấn về những mất mát, minh chứng cho những gì tàn bạo nhất của giặc ngoại xâm. Nơi này đã đi vào lịch sử, biểu tượng của sự bi tráng và lòng anh dũng của những con người yêu nước, đặt sự độc lập và vận mệnh dân tộc lên hàng đầu.', 4.8, 611),
    (92, 43, 'Di tích lịch sử', 'Địa đạo Vịnh Mốc', 17.073, 107.111, 'Công trình này ở sâu lòng đất, được người dân đào trong kháng chiến chống Mỹ. Địa đạo gồm có nhiều khu vực như trường học, kho hậu cần, bệnh viện, khu quân sự và khu gia đình.', 4.6, 3218),
    (93, 43, 'Thiên nhiên', 'Bãi biển Cửa Tùng', 17.0228273, 107.1104295, 'Mùa hè đến bãi biển này, bạn sẽ thấy được nét đẹp bình yên của biển xanh, cát trắng. Khung cảnh tĩnh lặng vào buổi chiều hoàng hôn khiến bao trái tim bị mê hoặc.', 4.3, 815),
    (94, 43, 'Cảnh quan nông nghiệp', 'Đồi hoa Miền Viên Thảo', 16.64574858585175, 106.7259382111224, 'Nổi bật với cánh đồng hoa rực rỡ và nở rộ quanh năm. Thời tiết ở đây cực kỳ mát mẻ nên việc trồng hoa khá thuận lợi. Địa điểm du lịch Quảng Trị có đủ hoa hồng, cúc họa mi, hoa cải vàng. Đặc biệt, nếu bạn yêu thích hoa tam giác mạch thì không thể bỏ hoa Miền Viên Thảo.', 4.1, 47),
    (95, 43, 'Thiên nhiên', 'Đỉnh Cu Vơ', 16.7015204, 106.656808, 'Rất thích hợp cho nhóm bạn đi phượt. Cực kì thu hút các bạn trẻ đến để săn mây. Vào buổi sáng sớm, đứng ở ngọn núi, mở ra trước mắt bạn là những tầng mây trắng. Khoảnh khắc ánh nắng mặt trời rọi xuống thực sự đẹp biết bao.', 4.8, 102),
    (96, 44, 'Chợ', 'Chợ nổi Ngã Năm', 9.5663969, 105.597209, 'bày bán đủ các loại mặt hàng từ thực phẩm cho đến nhu yếu phầm. Đặc biệt hơn hết, không thể không nhắc đến các ghe/ xuồng đầy ắp các loại trái cây nhiệt đới đặc trưng tùy mùa.', 4.4, 78),
    (97, 44, 'Tôn giáo và tín ngưỡng', 'Chùa Dơi', 9.578940019479788, 105.97220443719678, 'Kiến trúc của ngôi chùa này được xem là tiêu biểu của Phật giáo Nam tông Khmer, chùa được xây dựng vào thế kỷ 16 nhưng cho đến nay toàn bộ công trình còn giữ được tình trạng tốt và vẫn là nơi sinh hoạt tôn giáo mang ý nghĩa quan trọng của người dân trong vùng. Điều Đặc biệt khi đi đây là du khách sẽ thấy hàng nghìn con dơi khá lớn treo mình trên cây trong khuôn viên chùa giống như chúng đã quen thuộc với nơi này vậy', 4.2, 4042),
    (98, 44, 'Thiên nhiên', 'Vườn cò Tân Long', 9.5395328, 105.6443554, 'Vườn cò Tân Long tại khu vực Ngã Năm, Sóc Trăng, là điểm tham quan có nhiều chim cò trú ngụ trong vườn cây.', 3.9, 118),
    (99, 44, 'Thiên nhiên', 'Biển Hồ Bể', 9.3533864, 106.160845799999, 'Khu vực này được hình thành do sự bãi bồi và quá trình xâm lấn của nước biển, làm nên một vùng hồ trũng rộng lớn. Bãi biển hồ này còn được thiên nhiên ưu ái bằng một bờ cát trắng dài hàng cây số. Do chưa đưa vào khai thác du lịch mạnh, bãi biển vẫn giữ được nét hoang sơ, tự nhiên vốn có mang lại sự yên bình, tự do cho du khách', 3.8, 939),
    (100, 44, 'Tôn giáo và tín ngưỡng', 'Chùa Som Rong', 9.623636, 105.9819457, 'Là một nơi đặc biệt quan trọng không chỉ do tín ngưỡng tôn giáo, mà còn do ngôi chùa này có một thư viện lớn với hơn 1500 đầu sách, phục vụ cho các bạn thiếu nhi, bà con tại nơi này. Ngôi bảo tháp được phủ một màu xám huyền bí thay vì màu vàng thường gặp; Pho tượng phật nằm dài hơn 63 mét, cao hơn mặt đất khoảng 28 mét, cộng thêm chiều cao 22 mét khiến cho pho tượng vô cùng uy nghi; chùa Som Rong thường được nhiều khách du lịch lựa chọn ghé thăm', 4.8, 878),
    (101, 45, 'Thiên nhiên', 'Mộc Châu', 20.844986, 104.637836, 'với đặc sản là những mùa hoa ban, hoa anh đào, hoa mận, hoa cải vàng… tràn ngập hương sắc. Mộc Châu cũng là cái tên kinh điển nhất khi nhắc đến du lịch vùng Tây Bắc với cung đường phượt đẹp như tranh vẽ', NULL, 0),
    (102, 45, 'Thiên nhiên', 'Ngũ động Bản Ôn', 20.8731591, 104.71174649999999, 'Đây là hệ thống gồm 5 hang động được người dân địa phương phát hiện lần đầu tiên vào năm 2006. Vì tại đây chưa có nhiều dịch vụ du lịch nên những hang động vẫn giữ được vẻ đẹp hoang sơ, huyền bí. Bên trong hang được điểm xuyến bởi những khối đá nhũ thạch khổng lồ với hình thù độc đáo.', 4.2, 206),
    (103, 45, 'Thiên nhiên', 'Rừng thông bản Áng', 20.8283779, 104.6280971, 'Khu rừng có tổng diện tích lên đến 43ha với bầu không khí trong lành và khung cảnh thông xanh trập trùng trông rất mát mắt. Bạn có thể trải nghiệm cắm trại qua đêm tại rừng thông bản Áng để thỏa sức hít thở khí trời se lạnh và đón mình bình.', 4.2, 610),
    (104, 45, 'Thiên nhiên', 'Thác Dải Yếm', 20.820206, 104.591076, 'Thác cao hơn 100m, chia thành 2 tầng chính. Trong đó tầng thứ nhất có tổng cộng 9 bậc, tầng thứ hai có 5 bậc. Vào độ từ tháng 4 đến tháng 10 hàng năm, khi lượng nước đổ về nhiều sẽ tạo nên những dòng chạy mạnh mẽ, tung bọt trắng xóa rất đẹp mắt', 4.2, 1916),
    (105, 45, 'Thiên nhiên', 'Đỉnh Tà Xùa', 21.4337722, 104.3038885, 'Từ trên đỉnh, bạn có thể phóng tầm mắt chiêm ngưỡng khung cảnh hùng vĩ xung quanh với những dải ruộng bậc thang xanh mướt, thấp thoáng xa xa là mái lá khói bếp, tay có thể chạm đến mây trời.', 4.8, 225),
    (106, 54, 'Thiên nhiên', 'Núi Bà Đen', 11.381431, 106.171175, 'núi Bà Đen còn được biết đến như “nóc nhà” của Nam Bộ với đỉnh cao nhất là 986 m, diện tích 24 km², Nếu yêu thích vẻ đẹp bao la của đất trời, muốn chiêm ngưỡng cảnh đẹp từ trên cao thì có thể lựa chọn di chuyển bằng cáp treo từ chân núi lên đỉnh núi.', 4.6, 7951),
    (107, 54, 'Tôn giáo và tín ngưỡng', 'Tòa thánh Tây Ninh', 11.303746, 106.133717, 'Tòa thánh chính là địa điểm du lịch Tây Ninh dành cho những dân phượt muốn tìm hiểu về nét văn hóa và nét kiến trúc tiêu biểu tại nơi đây, Phong cách thiết kế của công trình vô cùng độc đáo, các chi tiết được trạm trổ hoa văn kỳ công và mang nhiều nét biểu tượng cho văn hóa mảnh đất này.', 4.7, 5687),
    (108, 54, 'Thiên nhiên', 'Hồ Dầu Tiếng', 11.38417, 106.36361, 'Hồ chứa nước Dầu Tiếng trên lưu vực sông Sài Gòn, trải trên địa bàn Tây Ninh, Bình Dương và Bình Phước theo địa giới của bộ dữ liệu gốc. Hồ phục vụ thủy lợi và có cảnh quan mặt nước rộng.', 4.5, 1245),
    (109, 54, 'Di tích lịch sử', 'Tháp Chót Mạt', 11.46368, 106.010233, 'Tòa tháp này có kiến trúc rất đặc biệt đó chính là được xây dựng nhỏ dần lên phía trên nhưng lại không hề có đỉnh chóp. Người Óc Eo rất khéo léo và thông minh khi xây dựng công trình, họ không hề chút xi măng nào làm vật liệu kết dính. Khi đến đây tham quan, du khách có thể thoải mái check in tại một không gian vô cùng yên bình và mang nét hoài cổ của địa điểm du lịch Tây Ninh này.', 4.4, 196),
    (110, 54, 'Thiên nhiên', 'Vườn quốc gia Lò Gò - Xa Mát', 11.5909501, 105.8859374, 'tới đây, du khách có thể ngắm nhìn các loài động, thực vật quý hiếm mà bạn khó có cơ hội được nhìn ngắm ngoài đời. Có rất nhiều những loài động vật quý hiếm được liệt kê vào sách đỏ. Ngoài ra, du khách cũng có thể trải nghiệm rất nhiều những hoạt động như đạp xe xuyên rừng, khám phá rừng bằng đường sông,…', 4.3, 332),
    (111, 48, 'Tôn giáo và tín ngưỡng', 'Chùa Keo', 20.36055556, 106.29722222, 'Chùa Keo ở Thái Bình được xếp hạng là ngôi chùa cổ đẹp nhất tại Việt Nam. Chùa được xây dựng theo kiến trúc cổ kín từ thời nhà Lê. Chính vì lẽ đó mà chùa Keo được xem là một trong những địa điểm check-in Thái Bình mà bạn nhất định phải đến tham quan.', 4.6, 3669),
    (112, 48, 'Thiên nhiên', 'Bãi biển Đồng Châu', 20.40027778, 106.57611111, 'Còn giữ nguyên vẻ đẹp hoang sơ thì hãy đến với bãi biển Đồng Châu. Với bờ cát trải dài 5km ôm lấy mặt biển mênh mông, xanh mướt đã vẻ nên một địa điểm du lịch độc đáo tại Bắc Trung Bộ. hững chiếc chòi canh nhấp nhô trên mặt nước tạo nên cảnh sắt thật là hữu tình.', 4.2, 1299),
    (113, 48, 'Thiên nhiên', 'Bãi biển Cồn Đen', 20.4874124999999, 106.603849599999, 'hình ảnh đẹp nhất của biển và sự hoang sơ của khu rừng nguyên sinh. Đặc biệt, vào thời điểm bình minh và hoàng hôn thì vẻ đẹp nơi đây lại trở nên quyến rũ đến kỳ lạ, lúc này cũng là khoảnh khắc được nhiều người săn đón nhất. Với vẻ đẹp trong lành từ không khí cho đến mặt nước biển trong xanh cùng bãi cát trắng thì đây đích thị là một background cực xịn', 3.5, 366),
    (114, 48, 'Tôn giáo và tín ngưỡng', 'Nhà thờ Bác Trạch', 20.3653994, 106.4772685, 'Đây chính là một trong những nhà thờ lớn nhất Việt Nam hiện nay với hoa văn trang trí công phu theo lối kiến trúc Roman. Với vẻ đẹp này chắc chắn nhà thờ Bác Trạch là một địa điểm check-in Thái Bình độc đáo dành cho bạn.', 4.7, 786),
    (115, 48, 'Làng nghề và thủ công', 'Làng dệt chiếu Hới', 20.64611111, 106.14333333, 'Nổi tiếng với những làng nghề truyền thống gần hàng trăm năm tuổi. bạn còn được hiểu thêm về cuộc sống giản dị của người dân trong làng. Và bạn sẽ được người dân giới thiệu về quy trình để tạo ra được một một chiếc chiếu truyền thống, từ thu hoạch chế biến cói cho tới khâu thành phẩm. Những trải nghiệm này sẽ là một kỷ niệm khó quên cho chuyến đi của bạn.', NULL, 0),
    (116, 49, 'Thiên nhiên', 'Hồ Núi Cốc', 21.57944444, 105.69388889, 'Du khách có thể trải nghiệm ngồi thuyền thúng, khám phá động Thế giới Cổ tích và Âm phủ, động Ba Cây Thông, tham quan quần thể Thuyết Nhân Quả - Chùa Thiêng Thác Vàng, ngôi chùa nằm trong lòng Phật lớn nhất miền Bắc được ghi nhận kỷ lục Guniess.', 4.2, 1723),
    (117, 49, 'Cảnh quan nông nghiệp', 'Đồi chè Tân Cương', 21.544137, 105.759957, 'Một trong những địa điểm du lịch Thái Nguyên nổi tiếng chắc chắn không thể quên kể đến đó chính là đồi chè Tân Cương. Đây là một địa điểm thu hút sự quan tâm từ đông đảo khách du lịch nhờ vào cảnh quan thiên nhiên tuyệt đẹp, được bao phủ bởi một sắc xanh mát lạnh. Bất cứ ai đến đồi chè Tân Cương du lịch cũng đều có thể cảm nhận được sự tươi mới từ sâu trong tâm hồn, giúp bạn cảm thấy dễ chịu hơn bao giờ hết.', NULL, 0),
    (118, 49, 'Thiên nhiên', 'Hồ Vai Miếu', 21.5307751, 105.6454158, 'Hồ Vai Miếu nằm dưới chân dãy Tam Đảo, thuộc khu vực Ký Phú, Đại Từ, Thái Nguyên. Hồ có cảnh quan mặt nước giữa đồi núi, phù hợp với nội dung khám phá thiên nhiên.', 4.7, 17),
    (119, 49, 'Thiên nhiên', 'Động Linh Sơn', 21.62787, 105.867057, 'Động Linh Sơn tỉnh Thái Nguyên có diện tích rộng rãi, vào mùa hè rất mát mẻ và mùa đông sẽ ấm áp vô cùng. Động nằm tại khu vực lưng chừng núi đá rộng lớn nên đã được người dân nơi đây lựa chọn xây dựng chùa thờ Phật. Cứ vào các ngày rằm, mùng một, người dân từ Thái Nguyên và nhiều tỉnh thành lân cận khác đều sẽ đến đây dâng hương lễ Phật rất náo nhiệt.', 4.5, 6),
    (120, 49, 'Thiên nhiên', 'Thác Đát Đắng', 21.6426896, 105.5198836, 'bạn sẽ có cảm giác hệt như đang lạc bước vào một không gian mới mẻ, được tránh xa hoàn toàn sự xô bồ và náo nhiệt nơi phố thị. Cảnh núi rừng hùng vĩ, dòng nước xanh trong mát lành chính là những thứ ấn tượng khiến bạn có cảm giác thật sự thư giãn và mong muốn được tận hưởng sự yên bình hiếm thấy này mãi không thôi.', 4.3, 44),
    (121, 46, 'Thiên nhiên', 'Suối Hiêu', 20.466886, 105.222092, 'Nằm giữa khu rừng xanh mướt và những cánh đồng lúa bình yên, suối Hiêu cứ như thế mà yên ả chảy ríu rít ngày ngày để mang đến một địa điểm check-in Thanh Hóa vô cùng thơ mộng. Như một đóa hồng có gai, suối mang vẻ đẹp quyến rũ đến nao lòng nhưng lại có khả năng hóa đá tạm thời những gì rơi xuống bởi hàm lượng vôi rất cao.', 5, 2),
    (122, 46, 'Cảnh quan nông nghiệp', 'Ruộng bậc thang Pù Luông', 20.4493422, 105.1579453, 'Đến Thanh Hóa mà không đặt chân đến các đến các ruộng bậc thang Pù Luông để check-in thì thật là một thiếu sót to lớn. Ruộng bậc thang Pù Luông vừa là niềm tự hào của nhân dân ta, vừa là địa điểm check-in Thanh Hóa siêu hot', NULL, 0),
    (123, 46, 'Thiên nhiên', 'Suối cá Thần Cẩm Thủy', 20.251958, 105.390441, 'Suối cá Thần là địa điểm gắn liền với tín ngưỡng của người dân tộc Mường, bởi nơi đây có lượng sinh sống đặc biệt dày đặc. Hiện nay, suối cá cũng đã trở thành một trong những địa điểm check-in Thanh Hóa độc đáo và nổi tiếng mà bạn có thể thêm vào lịch trình của mình nhé.', 4.3, 1325),
    (124, 46, 'Thiên nhiên', 'Vườn quốc gia Bến En', 19.61666667, 105.525, 'là nơi sinh sống của nhiều loài động thực vật quý hiếm có thể kể đến lim xanh, bù hương, chò chỉ… gấu ngựa, phượng hoàng đất…Vườn Quốc gia Bến En được ví như lá phổi xanh xanh của Thanh Hóa bởi những cánh rừng xanh bất tận. Và xen lẫn vào màu xanh ấy là những hang động, dải núi đá cao gập ghềnh đã tạo nên những địa điểm check-in Thanh Hóa độc đáo và đĩnh đạc nhất.', 4.2, 129),
    (125, 46, 'Thiên nhiên', 'Động Từ Thức', 20.04305556, 105.9680556, 'Đào và được tạo thành từ muôn vàn hình dạng nhũ đá. Sâu bên trong động còn có một hồ nước nhỏ tạo nên một bức tranh vô cùng thơ mộng.', 4.4, 750),
    (126, 50, 'Di tích lịch sử', 'Đại Nội Huế', 16.470231, 107.577251, 'Nằm ở bờ Bắc của dòng sông Hương thơ mộng trữ tình, Đại Nội Huế với kiến trúc nghệ thuật cung đình và vườn hào độc đáo. Cũng là trung tâm hành chính, chính trị của triều đình nhà Nguyễn và nơi sinh hoạt của nhà vua hoàng gia ngày xưa.', 4.6, 24549),
    (127, 50, 'Tôn giáo và tín ngưỡng', 'Chùa Thiên Mụ', 16.4537195, 107.5445808, 'Ngôi chùa này là điểm tham quan Huế nổi tiếng và không thể thiếu trong mọi hành trình đến khám phá Huế của du khách.Cách trung tâm thành phố Huế khoảng 5km về phía Tây, với một tên gọi khác là chùa Linh Mụ, chùa nằm trên đồi Hà Khê, nhìn xuống dòng Hương thơ mộng. Ngôi chùa mang vẻ đẹp cổ kính lâu đời với những khuông viên rộng rãi,khung cảnh thanh tịnh và đặc biệt hình tháp Phước Duyên 7 tầng tại sân trước của chùa được xem là biểu tượng đặc trưng cho thành phố Huế', 4.6, 20332),
    (128, 50, 'Di tích lịch sử', 'Lăng Khải Định', 16.39888889, 107.59027778, 'Nhắc đến Huế người ta không khỏi đề cập đến lăng tẩm thời Nguyễn. Tour du lịch của bạn sẽ thú vị hơn, nếu đừng chân ghé thăm điểm đến Lăng Khải Định. Du khách sẽ được chiêm ngưỡng đỉnh cao nghệ thuật tạo hình sành sứ và thủy tinh rất tinh xảo của bàn tay nghệ nhân thời xưa qua, bởi lẽ. Có thể nói lăng Khải Định là một công trình kết hợp độc đáo giữa kiến trúc Đông – Tây tinh xảo.', 4.5, 17196),
    (129, 50, 'Di tích lịch sử', 'Lăng Minh Mạng', 16.38777778, 107.56777778, 'Lăng Minh Mạng còn gọi là Hiếu Lăng, nằm trên núi Cẩm Khê, gần ngã ba Bằng Lãng là nơi hội lưu của hai dòng Hữu Trạch và Tả Trạch hợp thành sông Hương, cách cố đô Huế 12 km. Lăng Minh Mạng được xây dựng từ năm 1840 đến năm 1843 thì hoàn thành, huy động tới mười nghìn thợ và lính.', 4.5, 6317),
    (130, 50, 'Công trình và không gian xây dựng', 'Cầu Tràng Tiền', 16.46888889, 107.58861111, 'Một trong những chiếc cầu lâu đời tại Huế và trở thành biểu tượng du lịch của Huế không ai khác chính là cầu Tràng Tiền bắc qua sông Hương thơ mộng cũng là một “nàng thơ” kiều diễm của không ít văn nghệ sĩ trong nước.', 4.7, 744),
    (131, 51, 'Thiên nhiên', 'Biển Tân Thành', 10.2902823, 106.7820742, 'với làn nước trong xanh và bãi cát trắng, biển Tân Thành sở hữu vẻ đẹp rất riêng với bãi cát đen dài hơn 7km. Dọc theo bãi biển là cầu cảng màu xanh lam đặc trưng và các khu lưới người dân dựng lên để đánh bắt cá, nghêu…', 4.4, 1496),
    (132, 51, 'Công trình và không gian xây dựng', 'Cầu Mỹ Thuận', 10.27755556, 105.90997222, 'Cầu dây văng Mỹ Thuận bắc qua sông Tiền, nối khu vực Tiền Giang và Vĩnh Long, khánh thành năm 2000.', 4.9, 54),
    (133, 51, 'Tôn giáo và tín ngưỡng', 'Nhà Thờ Cái Bè', 10.3379192, 106.0352714, 'Sở hữu nét kiến trúc Roman đặc trưng, nhà thờ Cái Bè không những đóng vai trò quan trọng trong đời sống tôn giáo của người dân nơi đây mà còn là địa điểm tham quan hấp dẫn ở Tiền Giang. Điểm nổi bật nhất của nhà thờ Cái Bè là tháp chuông được xem là cao nhất khu vực Đồng bằng Sông Cửu Long. Ngoài ra, chính diện nhà thờ hướng ra ngã ba sông Cái Bè tựa như đang ôm trọn đất trời. Khuôn viên được bố trí nhiều cây xanh, mang đến cảnh quan đẹp mắt', 4.6, 231),
    (134, 51, 'Tôn giáo và tín ngưỡng', 'Chùa Linh Thứu', 10.3741627, 106.3026897, 'Đây là một trong những ngôi chùa có lịch sử lâu đời nhất tại tỉnh Tiền Giang. Đặc biệt hơn, nơi này gắn liền với câu chuyện thoát chết của vua Gia Long được lưu truyền qua nhiều thế hệ. Đây là một trong những ngôi chùa có lịch sử lâu đời nhất tại tỉnh Tiền Giang. Đặc biệt hơn, nơi này gắn liền với câu chuyện thoát chết của vua Gia Long được lưu truyền qua nhiều thế hệ.', 4.6, 206),
    (135, 51, 'Tôn giáo và tín ngưỡng', 'Nhà thờ chính tòa Mỹ Tho', 10.361439729155896, 106.36492568303858, 'Nhà thờ chính tòa của Giáo phận Mỹ Tho, tại số 32 Hùng Vương, khu vực Mỹ Tho, Tiền Giang. Công trình có giá trị kiến trúc và sinh hoạt tôn giáo của cộng đồng Công giáo.', 4.7, 450),
    (136, 47, 'Chợ', 'Chợ Bến Thành', 10.77252069, 106.69801918, 'Đây là một trong những địa điểm du lịch Thành phố Hồ Chí Minh nổi tiếng nhất nằm ngay trung tâm thành phố và luôn tấp nập người ra vào mua bán, du khách check in mỗi ngày. Chợ Bến Thành buôn bán tất tần tật những mặt hàng từ thực phẩm, vải vóc, quần áo, đồ gia dụng, đặc sản Sài Gòn,… và quan trọng là khu ẩm thực cực kỳ hấp dẫn ở chợ và những góc check in ấn tượng sẽ làm bạn luôn muốn lưu lại nơi đây thật lâu.', 4, 87779),
    (137, 47, 'Di tích lịch sử', 'Dinh Độc Lập', 10.777108, 106.695441, 'Nơi đây đã được công nhận là 1 trong 10 di tích quốc gia đặc biệt của Việt Nam vào năm 2009. Dinh Độc Lập là nơi trưng bày và lưu giữ những hình ảnh, hiện vật giá trị từ những năm của thế kỷ 19 theo từng chủ đề khác nhau. Đặc biệt nơi đây vẫn còn giữ nguyên nội thất của những căn phòng quan trọng như phòng khánh tiết, phòng nội các,....', 4.5, 48922),
    (138, 47, 'Tôn giáo và tín ngưỡng', 'Nhà thờ Đức Bà Sài Gòn', 10.779722, 106.699167, 'Cũng nằm ngay trung tâm quận 1, nhà thờ Đức Bà là địa điểm du lịch thành phố Hồ Chí Minh mà bạn nhất định phải ghé đến. Nhà thờ Đức Bà là một công trình kiến trúc độc đáo mang đậm phong cách Châu Âu, là nơi sinh hoạt và tổ chức các buổi Thánh lễ cho những người theo đạo Công giáo ở Sài Thành.', 4.4, 29222),
    (139, 47, 'Bảo tàng', 'Bảo tàng Lịch sử Thành phố Hồ Chí Minh', 10.78484, 106.70759, 'Bảo tàng lịch sử Việt Nam được xây dựng và hoạt động từ những năm đầu thế kỷ 20, là nơi lưu giữ và bảo tồn những hình ảnh, cổ vật từ thuở sơ khai đến nay. Bảo tàng lịch sử Việt Nam thu hút phần lớn những du khách yêu lịch sử và kiến trúc pha trộn giữa 2 phong cách Á – Âu độc đáo.', 4.5, 4230),
    (140, 47, 'Di tích lịch sử', 'Địa đạo Củ Chi', 11.061, 106.526, 'Nơi đây là di tích quốc gia đặc biệt, gắn liền với lịch sử chiến tranh Việt Nam, từng là căn cứ địa quan trọng và cũng là nơi sinh hoạt chung bao gồm bệnh xá, nhà bếp, nơi làm việc,… của quân đội ta trong cuộc kháng chiến chống quân xâm lược, giành lại toàn vẹn lãnh thổ. Bên cạnh đó, bên trong địa đạo Củ Chi còn tái hiện tại cuộc sống của họ qua những qua những mô hình người và vật rất chân thật, ấn tượng. Nơi đây là một trong những điểm đến hấp dẫn của những tour Hồ Chí Minh mà bạn không nên bỏ qua trong chuyến đi của mình.', 4.6, 18468),
    (141, 1, 'Thiên nhiên', 'Rừng Tràm Trà Sư', 10.585556, 105.058611, 'Khu rừng tràm đẹp nhất và nổi tiếng nhất Việt Nam', 4.4, 7661),
    (142, 1, 'Thiên nhiên', 'Hồ Soài So', 10.3919811, 105.0006341, 'Hồ nước nhân tạo lớn nhất An Giang', 4.4, 186),
    (143, 1, 'Tôn giáo và tín ngưỡng', 'Chùa Lầu', 10.6081247, 104.9601727, 'Là một ngôi chùa đã có lịch sử hơn 130 năm', 4.6, 854),
    (144, 1, 'Tôn giáo và tín ngưỡng', 'Miếu Bà Chúa Xứ', 10.682254, 105.080132, 'Miếu Bà Chúa Xứ là một trong những địa điểm tâm linh nổi tiếng nhất An Giang', 4.7, 5790),
    (145, 1, 'Tôn giáo và tín ngưỡng', 'Thiền viện Trúc Lâm An Giang', 10.2536802, 105.270966899999, 'Là một điểm đến tâm linh và du lịch vô cùng hấp dẫn ở miền Tây', 4.6, 1040),
    (146, 2, 'Thiên nhiên', 'Núi Dinh Vũng Tàu', 10.5375, 107.12916667, 'Núi Dinh nổi bật với những vách đá dựng đứng, tạo nên một bức tranh thiên nhiên hùng vĩ', 4.6, 838),
    (147, 2, 'Thiên nhiên', 'Bãi Sau', 10.3275, 107.08805555556, 'Bãi Sau được biết đến là một trong những bãi biển đẹp và lớn nhất Việt Nam', 4.4, 13547),
    (148, 2, 'Thiên nhiên', 'Hồ Tràm', 10.535094, 107.399238, 'Là một trong những bãi biển đẹp nhất khu vực miền Nam', 4.4, 431),
    (149, 2, 'Thiên nhiên', 'Suối Ồ', 10.5673558, 107.567002899999, 'Nơi đây nổi tiếng với vẻ đẹp hiếm có, vừa có suối nước ngọt, vừa có bãi biển nước mặn giao hòa trong cùng một khu vực.', 3.5, 410),
    (150, 2, 'Thiên nhiên', 'Côn Đảo Vũng Tàu', 8.682374, 106.607208, 'Là một quần đảo nổi tiếng với vẻ đẹp thiên nhiên hoang sơ, mà còn mang đậm dấu ấn lịch sử với các di tích gắn liền thời kỳ chiến tranh.', 4.6, 721),
    (151, 8, 'Tôn giáo và tín ngưỡng', 'Chùa Bổ Đà', 21.2425, 106.05222222222223, 'Là một trong những ngôi chùa cổ nổi tiếng và đặc sắc nhất vùng Kinh Bắc', 4.7, 2160),
    (152, 8, 'Thiên nhiên', 'Thác Thùm Thùm', 21.2446724, 106.4743427, 'Là một điểm đến hoang sơ và tuyệt đẹp giữa lòng thiên nhiên', 4.2, 179),
    (153, 8, 'Thiên nhiên', 'Hồ Cấm Sơn', 21.534781, 106.565012, 'Là một trong những hồ nước ngọt lớn nhất miền Bắc Việt Nam', 4.3, 294),
    (154, 8, 'Tôn giáo và tín ngưỡng', 'Đền Trung', 21.267171, 106.4845445, 'Đây là một trong ba ngôi đền chính thờ các vua Hùng và gắn liền với truyền thuyết dựng nước của dân tộc Việt Nam', 4.5, 10),
    (155, 8, 'Thiên nhiên', 'Hồ Khuôn Thần', 21.4558886, 106.5206077, 'Là một điểm đến lý tưởng với vẻ đẹp thiên nhiên thơ mộng và không khí trong lành', 4.5, 70),
    (156, 9, 'Thiên nhiên', 'Hồ Ba Bể', 22.405278, 105.615278, 'Hồ nước ngọt tự nhiên thuộc Vườn quốc gia Ba Bể, khu vực Bắc Kạn, bao quanh bởi núi đá vôi và rừng. Địa danh gắn với cảnh quan hồ, hoạt động đi thuyền và bản làng ven hồ.', 4.5, 1289),
    (157, 9, 'Thiên nhiên', 'Động Puông', 22.4575, 105.65777778, 'Là một hang động đẹp với những thạch nhũ kỳ vĩ', 4.5, 223),
    (158, 9, 'Thiên nhiên', 'Thác Đầu Đẳng', 22.4526, 105.570412, 'Đây là địa điểm du lịch sinh thái lý tưởng.', 4.3, 356),
    (159, 9, 'Làng, bản và phố cổ', 'Bản Pác Ngòi', 22.386412, 105.6398778, 'Đây là một bản làng của người Tày, nổi bật với nét văn hóa truyền thống', 4, 2),
    (160, 9, 'Thiên nhiên', 'Động Nàng Tiên', 22.2415487, 106.1532452, 'Đây là một hang động kỳ vĩ với thạch nhũ hình dạng đa dạng, gắn liền với truyền thuyết về nàng tiên xinh đẹp.', NULL, 0),
    (161, 7, 'Tôn giáo và tín ngưỡng', 'Chùa Quan Đế', 9.2803182, 105.723162899999, 'Là một ngôi chùa cổ kính, thờ Quan Công – một vị tướng nổi tiếng trong lịch sử Trung Quốc', 4.6, 130),
    (162, 7, 'Thiên nhiên', 'Biển Bạc Liêu', 9.20367119999999, 105.7434696, 'Biển Bạc Liêu có bờ biển dài, là một điểm đến du lịch nghỉ dưỡng tuyệt vời tại miền Tây Nam Bộ', NULL, 0),
    (163, 7, 'Thiên nhiên', 'Cây Xoài Cổ Thụ', 9.2479108, 105.7814312, 'Đây là cây xoài lớn tuổi, được xem là biểu tượng của sự trường thọ và thịnh vượng.', 4.4, 248),
    (164, 7, 'Di tích lịch sử', 'Nhà Công tử Bạc Liêu', 9.284084499999999, 105.7238055, 'Ngôi nhà này từng là nơi sinh sống của công tử Bạc Liêu, một nhân vật nổi tiếng trong lịch sử.', 4.4, 4103),
    (165, 7, 'Công trình và không gian xây dựng', 'Đồng hồ Thái Dương (Bạc Liêu)', 9.2856471, 105.7227156, 'Đồng hồ đá do nhà bác vật Lưu Văn Lang chế tạo, nằm tại khu vực trung tâm Bạc Liêu. Công trình xác định giờ dựa trên ánh sáng mặt trời và được bảo tồn như một di tích.', 4.7, 23),
    (166, 10, 'Tôn giáo và tín ngưỡng', 'Chùa Phật Tích', 21.10666667, 106.0125, 'Đây là một trong những ngôi chùa cổ, gắn liền với lịch sử Phật giáo Việt Nam.', 4.6, 3026),
    (167, 10, 'Tôn giáo và tín ngưỡng', 'Chùa Bút Tháp', 21.06083, 106.0222, 'Chùa Bút Tháp nằm ở Bắc Ninh, là một ngôi chùa nổi tiếng với kiến trúc độc đáo và tượng Phật Bà Quan Âm.', 4.7, 502),
    (168, 10, 'Làng nghề và thủ công', 'Làng tranh Đông Hồ', 21.0688056, 106.0754075, 'Làng tranh Đông Hồ ở Bắc Ninh là nơi sản xuất tranh dân gian nổi tiếng, với những bức tranh phản ánh đời sống nông thôn Việt Nam.', NULL, 0),
    (169, 10, 'Tôn giáo và tín ngưỡng', 'Đền bà Chúa Kho', 21.2052334, 106.0850561, 'Đền Bà Chúa Kho ở Bắc Ninh là nơi thờ bà Chúa Kho, một trong những vị thần được thờ cúng linh thiêng nhất ở Việt Nam', 4.6, 5859),
    (170, 18, 'Chợ', 'Chợ Ninh Hiệp', 21.07861111, 105.9475, 'Chợ Ninh Hiệp là một trong những khu chợ nổi tiếng nhất miền Bắc, chuyên buôn bán các mặt hàng vải vóc, quần áo.', 4.5, 1388),
    (171, 11, 'Khu vui chơi và nghỉ dưỡng', 'khu du lịch Cồn Phụng', 10.33330556, 106.3565, 'Cồn Phụng nằm ở Bến Tre, nổi bật với phong cảnh sông nước miệt vườn, vườn dừa và các hoạt động du lịch sinh thái.', 4.2, 642),
    (172, 11, 'Di tích lịch sử', 'Khu lăng mộ cụ Nguyễn Đình Chiểu', 10.037083, 106.582305, 'Khu lăng mộ Nguyễn Đình Chiểu ở Bến Tre là nơi yên nghỉ của nhà thơ, nhà văn nổi tiếng.', 4.6, 1016),
    (173, 11, 'Tôn giáo và tín ngưỡng', 'Chùa Tuyên Linh', 10.051152, 106.4116923, 'Chùa Tuyên Linh tại khu vực Minh Đức, Mỏ Cày Nam, Bến Tre, là cơ sở Phật giáo gắn với lịch sử địa phương và khu lưu niệm Nguyễn Sinh Sắc.', 4.7, 49),
    (174, 11, 'Tôn giáo và tín ngưỡng', 'Nhà thờ La Mã', 10.0994296, 106.4771878, 'Nhà thờ La Mã tại khu vực Hưng Nhượng, Giồng Trôm, Bến Tre, là địa điểm hành hương Công giáo gắn với Đức Mẹ La Mã Bến Tre.', 4.8, 1319),
    (175, 11, 'Khu vui chơi và nghỉ dưỡng', 'Khu du lịch sinh thái vườn Ba Ngói', 10.2583205, 106.0773036, 'Là khu du lịch sinh thái nổi bật ở Bến Tre, thu hút du khách với không gian xanh mát, thiên nhiên hoang sơ và các hoạt động vui chơi giải trí hấp dẫn.', NULL, 0),
    (176, 6, 'Thiên nhiên', 'Bãi tắm Quy Nhơn', 13.7643665, 109.2265855, 'Bãi tắm Quy Nhơn là một trong những bãi biển đẹp của miền Trung, nổi tiếng với cát trắng mịn và nước biển trong xanh.', 4.6, 1206),
    (177, 6, 'Thiên nhiên', 'Biển Kỳ Co', 13.8500185, 109.292630899999, 'Biển Kỳ Co thuộc Quy Nhơn, nổi tiếng với bãi biển hoang sơ, nước trong xanh và các rạn san hô đẹp mắt', 4.4, 4193),
    (178, 6, 'Thiên nhiên', 'Cù Lao Xanh', 13.61583333, 109.35055556, 'Cù Lao Xanh là một hòn đảo đẹp và hoang sơ tại Bình Định, với làn nước trong xanh và thiên nhiên chưa bị khai thác nhiều.', 4.7, 141),
    (179, 6, 'Thiên nhiên', 'Đầm Thị Nại', 13.825, 109.24166666666666, 'Đầm Thị Nại ở Bình Định là một trong những đầm lớn của miền Trung, nổi bật với khung cảnh thiên nhiên tĩnh lặng', 4.4, 70),
    (180, 6, 'Thiên nhiên', 'Hòn Khô', 13.7644024, 109.2993139, 'Hòn Khô là một hòn đảo nhỏ nằm gần Quy Nhơn, nổi tiếng với các bãi biển đẹp và làn nước trong vắt, thu hút du khách đến tham quan và tắm biển.', 4.5, 754),
    (181, 3, 'Tôn giáo và tín ngưỡng', 'Chùa Tây Tạng', 10.9775256, 106.6617572, 'Chùa Tây Tạng là một ngôi chùa nổi tiếng ở Bình Dương, thu hút du khách bởi kiến trúc độc đáo và không gian thanh tịnh.', 4.7, 4303),
    (182, 3, 'Khu vui chơi và nghỉ dưỡng', 'Khu du lịch Đại Nam', 11.043333333333333, 106.6325, 'Khu du lịch Đại Nam là một khu phức hợp bao gồm công viên, khu vui chơi, và các điểm tham quan khác, nổi bật tại Bình Dương, thu hút nhiều du khách đến tham quan và giải trí.', 4.4, 17840),
    (184, 3, 'Khu vui chơi và nghỉ dưỡng', 'Công viên Thành Phố mới Bình Dương', 11.0524088, 106.6786935, 'Công viên Thành Phố mới Bình Dương là một không gian xanh, là nơi lý tưởng cho các hoạt động thể thao, dạo bộ và thư giãn.', 4.6, 75),
    (185, 3, 'Tôn giáo và tín ngưỡng', 'Chùa Châu Thới', 10.91483, 106.8045558, 'Chùa Châu Thới là một ngôi chùa nổi tiếng ở Bình Dương, mang đậm nét văn hóa Phật giáo và có khung cảnh thanh tịnh, phù hợp cho các hoạt động tham quan tâm linh.', 4.6, 6251),
    (186, 4, 'Thiên nhiên', 'Núi Bà Rá', 11.816906, 107.000906, 'Ngọn núi cao nhất Bình Phước, có cáp treo dẫn lên đỉnh', 4.3, 344),
    (187, 4, 'Thiên nhiên', 'Trảng cỏ Bù Lạch', 11.8088982, 107.345534, 'Một cánh đồng cỏ rộng lớn, xanh mướt, được bao quanh bởi những khu rừng nguyên sinh và hồ nước', 4.4, 174),
    (188, 4, 'Di tích lịch sử', 'Khu di tích Tà Thiết', 11.7477875, 106.4719531, 'Nơi lưu giữ nhiều dấu ấn lịch sử của chiến tranh Việt Nam, với các di tích như hầm chỉ huy và kho quân khí', 4.4, 505),
    (189, 4, 'Thiên nhiên', 'Hồ Thác Mơ', 11.85777778, 107.01916667, 'Hồ nhân tạo lớn với cảnh quan thiên nhiên đẹp mắt', 4.3, 331),
    (190, 4, 'Thiên nhiên', 'Vườn quốc gia Bù Gia Mập', 12.0871991, 107.1564056, 'Vườn quốc gia tại khu vực Bù Gia Mập, Bình Phước, bảo tồn hệ sinh thái rừng và đa dạng sinh học. Nội dung khám phá phù hợp gồm rừng, cảnh quan thiên nhiên và tìm hiểu bảo tồn.', 4.3, 2687),
    (191, 5, 'Di tích lịch sử', 'Tháp Chàm Poshanư', 10.935947, 108.146173, 'Công trình kiến trúc cổ của người Chăm, mang giá trị lịch sử và văn hóa đặc sắc', 4.4, 1174),
    (192, 5, 'Công trình và không gian xây dựng', 'Hải đăng Kê Gà', 10.69596, 107.99134, 'Một trong những ngọn hải đăng lâu đời nhất Việt Nam, nằm trên một hòn đảo nhỏ giữa biển', 4.5, 2386),
    (193, 5, 'Thiên nhiên', 'Bàu Trắng', 11.066666666667, 108.41666666667, 'Hồ nước ngọt lớn giữa vùng cát trắng, còn gọi là "tiểu sa mạc Sahara" của Việt Nam.', 4.5, 1766),
    (194, 5, 'Làng, bản và phố cổ', 'Làng Chài Mũi Né', 10.9411708, 108.2787764, 'Khu vực làng chài truyền thống ven biển, nơi bạn có thể ngắm cảnh thuyền ghe tấp nập và trải nghiệm mua hải sản tươi sống trực tiếp từ ngư dân.', 4, 3494),
    (195, 5, 'Thiên nhiên', 'Hòn Rơm', 10.9549065, 108.3352589, 'Bãi biển nổi tiếng với làn nước trong xanh, bờ cát dài mịn và không khí yên bình', 4.4, 539),
    (196, 13, 'Thiên nhiên', 'Mũi Cà Mau', 8.6316666666667, 104.71388888889, 'Điểm cực Nam của Việt Nam, nơi có biểu tượng cột mốc quốc gia và hệ sinh thái rừng ngập mặn độc đáo', 4.8, 57),
    (197, 13, 'Thiên nhiên', 'Vườn Quốc Gia U Minh Hạ', 9.25138889, 104.94527778, 'Khu rừng tràm ngập nước nổi tiếng với hệ sinh thái đa dạng. Đây là nơi sinh sống của nhiều loài động, thực vật quý hiếm', 4.2, 846),
    (198, 13, 'Thiên nhiên', 'Hòn Đá Bạc', 9.179166, 104.800278, 'Cụm đảo nằm sát bờ biển, nổi bật với những phiến đá xếp chồng tự nhiên và hệ sinh thái biển phong phú', 4.2, 552),
    (199, 13, 'Thiên nhiên', 'Đầm Thị Tường', 8.999872, 104.935748, 'Được mệnh danh là “biển hồ giữa đồng bằng”, đây là đầm nước tự nhiên lớn nhất miền Tây', 4.3, 206),
    (200, 13, 'Tôn giáo và tín ngưỡng', 'Đền Thờ Bác Hồ', 9.1839854, 105.134884, 'Địa điểm tâm linh quan trọng, nơi người dân Cà Mau bày tỏ lòng thành kính với Chủ tịch Hồ Chí Minh', NULL, 0),
    (201, 14, 'Chợ', 'Chợ Nổi Cái Răng', 10.005, 105.746, 'Chợ nổi lớn và nổi tiếng nhất ở miền Tây Nam Bộ, nơi buôn bán nhộn nhịp trên sông. Du khách có thể trải nghiệm văn hóa sông nước, mua sắm đặc sản và thưởng thức ẩm thực trên thuyền.', 4.1, 8158),
    (202, 14, 'Công trình và không gian xây dựng', 'Cầu Cần Thơ', 10.03165278, 105.80863889, 'Cây cầu dây văng lớn nhất Đông Nam Á, nối liền Cần Thơ và Vĩnh Long. Đây là điểm check-in nổi tiếng và mang tính biểu tượng của vùng đất Tây Nam Bộ.', 4.8, 246),
    (203, 14, 'Khu vui chơi và nghỉ dưỡng', 'Làng Du Lịch Sinh Thái Ông Đề', 9.992319, 105.7075316, 'Điểm đến hấp dẫn với cảnh quan xanh mát, các trò chơi dân gian, chèo thuyền, và thưởng thức các món ăn đặc sản miền Tây.', 3.9, 1783),
    (204, 14, 'Tôn giáo và tín ngưỡng', 'Chùa Ông', 10.0341776, 105.7884576, 'Ngôi chùa cổ mang kiến trúc Trung Hoa, nổi tiếng linh thiêng và là nơi thờ Quan Công. Đây là địa điểm tham quan văn hóa độc đáo và check-in đẹp.', 4.6, 1116),
    (205, 14, 'Thiên nhiên', 'Cồn Sơn', 10.0700181, 105.762777399999, 'Khu sinh thái sông nước nổi tiếng, nơi du khách có thể tham quan làng cá bè, học làm bánh dân gian và trải nghiệm lối sống miệt vườn.', 4.3, 556),
    (206, 12, 'Thiên nhiên', 'Thác Bản Giốc', 22.855897, 106.722501, 'Một trong những thác nước đẹp nhất và lớn nhất Đông Nam Á, nằm trên biên giới Việt Nam - Trung Quốc. Thác được chia thành nhiều tầng với dòng nước trong xanh, tạo nên khung cảnh hùng vĩ.', 4.6, 11529),
    (207, 12, 'Thiên nhiên', 'Động Ngườm Ngao', 22.845328, 106.70617, 'Hang động dài hơn 2.1km, nổi bật với hệ thống thạch nhũ độc đáo và cảnh quan kỳ ảo. Động nằm gần thác Bản Giốc, là điểm đến lý tưởng để khám phá.', 4.7, 1324),
    (208, 12, 'Thiên nhiên', 'Núi Mắt Thần', 22.7782145, 106.3112857, 'Ngọn núi độc đáo với một lỗ lớn ở giữa, được gọi là "Mắt Thần." Đây là điểm check-in nổi tiếng với cảnh quan núi non tuyệt đẹp.', 4.8, 1501),
    (209, 12, 'Di tích lịch sử', 'Di tích rừng Trần Hưng Đạo', 22.5916057, 106.0407213, 'Nơi thành lập Đội Việt Nam Tuyên Truyền Giải Phóng Quân năm 1944, khởi nguồn của Quân đội Nhân dân Việt Nam. Khu di tích có giá trị lịch sử to lớn.', 4.5, 138),
    (210, 12, 'Làng nghề và thủ công', 'Làng rèn Phúc Sen', 22.6834316, 106.4087452, 'Làng nghề truyền thống nổi tiếng với sản phẩm dao kéo chất lượng cao. Du khách có thể tham quan quy trình rèn và mua sắm các sản phẩm thủ công.', 4.2, 118),
    (211, 59, 'Khu vui chơi và nghỉ dưỡng', 'Bà Nà Hills', 15.99555556, 107.99416667, 'Khu nghỉ dưỡng trên đỉnh núi với khí hậu mát mẻ, nổi tiếng với cây Cầu Vàng độc đáo, làng Pháp cổ điển và khu vui chơi trong nhà Fantasy Park.', 4.4, 99229),
    (212, 59, 'Công trình và không gian xây dựng', 'Cầu Rồng', 16.06111111, 108.22666667, 'Biểu tượng của thành phố Đà Nẵng, cây cầu có thiết kế hình rồng phun lửa và nước vào cuối tuần. Đây là điểm check-in và ngắm cảnh sông Hàn tuyệt đẹp.', 4.5, 9758),
    (213, 59, 'Thiên nhiên', 'Ngũ Hành Sơn', 16.00402, 108.2627745, 'Cụm núi đá vôi gồm 5 ngọn núi với hang động, chùa chiền, và khung cảnh thiên nhiên tuyệt đẹp. Nổi bật là động Huyền Không và chùa Tam Thai.', 4.4, 43219),
    (214, 59, 'Thiên nhiên', 'Bãi biển Mỹ Khê (Đà Nẵng)', 16.0704, 108.2461, 'Một trong những bãi biển đẹp nhất hành tinh, nổi tiếng với bãi cát trắng mịn, nước biển trong xanh, là nơi lý tưởng để tắm biển và các hoạt động thể thao dưới nước.', 4.7, 4707),
    (215, 59, 'Công trình và không gian xây dựng', 'Cầu Tình Yêu', 16.0632798999999, 108.229604099999, 'Cây cầu nhỏ bên sông Hàn với thiết kế lãng mạn, nơi các cặp đôi thường treo móc khóa tình yêu. Từ đây, bạn có thể ngắm nhìn tượng Cá Chép Hóa Rồng.', 4.6, 772),
    (216, 52, 'Thiên nhiên', 'Ao bà om', 9.917608099999999, 106.30409159999999, 'Ao Bà Om là một hồ nước tự nhiên, được bao quanh bởi hàng cây cổ thụ hàng trăm năm tuổi với rễ cây nổi lên thành những hình thù kỳ thú. Đây là một địa điểm du lịch yên bình, gắn liền với truyền thuyết và văn hóa Khmer.', 4.5, 1190),
    (217, 52, 'Tôn giáo và tín ngưỡng', 'Chùa Hang', 9.8870578, 106.345022199999, 'Chùa Hang nổi tiếng không chỉ vì kiến trúc độc đáo mà còn vì những tác phẩm điêu khắc gỗ tinh xảo của các nghệ nhân Khmer. Ngôi chùa này là điểm dừng chân lý tưởng cho những ai muốn khám phá nghệ thuật và văn hóa Khmer.', 4.5, 846),
    (218, 52, 'Thiên nhiên', 'Bãi biển Ba Động', 9.6234751, 106.5608165, 'bãi biển hoang sơ với cát mịn và sóng nhẹ, Ba Động là nơi thích hợp để thư giãn và thưởng thức các món hải sản tươi ngon. Đây là một trong những bãi biển hiếm hoi ở miền Tây Nam Bộ.', 4.6, 1180),
    (219, 52, 'Bảo tàng', 'Bảo tàng Văn hóa Khmer', 9.9161858, 106.30501679999999, 'Bảo tàng trưng bày các hiện vật, tư liệu về đời sống, văn hóa, nghệ thuật và lịch sử của người Khmer Nam Bộ, giúp du khách hiểu thêm về cộng đồng dân tộc này.', 4.5, 402),
    (220, 52, 'Tôn giáo và tín ngưỡng', 'Chùa Vàm Rây', 9.655278, 106.274725, 'Là ngôi chùa Khmer lớn nhất Việt Nam, chùa Vàm Rây gây ấn tượng bởi kiến trúc vàng rực rỡ, tượng Phật nằm khổng lồ và không gian tĩnh lặng.', 4.6, 557),
    (221, 53, 'Thiên nhiên', 'Thác Bản Ba', 22.337427, 105.067892, 'Thác Bản Ba thuộc xã Trung Hà, huyện Chiêm Hóa, là một cụm thác với 3 tầng chính đổ xuống từ độ cao khoảng 40 m. Thác được bao quanh bởi rừng núi hoang sơ, nước trong xanh và khí hậu mát mẻ quanh năm. Đây là điểm đến lý tưởng để hòa mình vào thiên nhiên.', 4.5, 133),
    (222, 53, 'Thiên nhiên', 'Hồ Thủy Điện Tuyên Quang', 22.36047222, 105.40102778, 'Hồ Na Hang được ví như "Hạ Long trên núi", nổi bật với mặt hồ trong xanh, các đảo núi đá vôi trập trùng, và rừng nguyên sinh bao quanh. Du khách có thể khám phá các địa danh như thác Khuổi Nhi, đền Pác Tạ, và tham gia du thuyền ngắm cảnh.', 4.6, 212),
    (223, 53, 'Tôn giáo và tín ngưỡng', 'Đền Hạ (Tuyên Quang)', 21.8130773, 105.2151908, 'Đền Hạ, còn gọi là đền Hiệp Thuận hoặc đền Tam Kỳ, là di tích thờ Mẫu tại khu vực trung tâm Tuyên Quang. Đền có liên hệ lễ hội với đền Thượng và đền Mẫu Ỷ La.', 4.6, 241),
    (224, 53, 'Thiên nhiên', 'Suối khoáng Mỹ Lâm', 21.765885, 105.1236254, 'Suối khoáng Mỹ Lâm nổi tiếng với nguồn nước khoáng nóng tự nhiên, có tác dụng chữa bệnh và thư giãn. Đây là khu du lịch nghỉ dưỡng hấp dẫn, kết hợp giữa trị liệu sức khỏe và cảnh sắc thiên nhiên tươi đẹp.', NULL, 0),
    (225, 53, 'Thiên nhiên', 'Thác Khuổi Nhi', 22.495480399999998, 105.3615803, 'hác Khuổi Nhi thuộc khu vực Na Hang, là một trong những thác nước đẹp nhất ở Tuyên Quang. Nước thác trắng xóa đổ xuống từ độ cao lớn, hòa quyện với thiên nhiên hùng vĩ tạo nên cảnh sắc thơ mộng.', NULL, 0),
    (226, 55, 'Thiên nhiên', 'Cù Lao An Bình', 10.2917762999999, 105.9797902, 'Cù Lao An Bình là một khu vực miệt vườn đặc trưng của miền Tây Nam Bộ, nổi tiếng với vườn cây ăn trái như chôm chôm, sầu riêng, măng cụt. Du khách có thể tham gia chèo xuồng, tham quan các làng nghề truyền thống và thưởng thức ẩm thực dân dã.', NULL, 0),
    (227, 55, 'Tôn giáo và tín ngưỡng', 'Chùa Tiên Châu', 10.2629972, 105.969111099999, 'Chùa Tiên Châu nằm trên cù lao An Bình, là một ngôi chùa cổ kính mang đậm nét kiến trúc Phật giáo. Ngôi chùa có không gian yên tĩnh, thanh bình, thu hút nhiều Phật tử và du khách đến chiêm bái.', 4.6, 141),
    (229, 55, 'Khu vui chơi và nghỉ dưỡng', 'Khu du lịch Vinh Sang', 10.2704084, 105.9536573, 'Khu du lịch Vinh Sang nằm trên cù lao An Bình, là nơi lý tưởng để trải nghiệm các trò chơi dân gian, tham gia câu cá sấu, chèo xuồng, hoặc khám phá các vườn trái cây.', 4.3, 2211),
    (230, 55, 'Tôn giáo và tín ngưỡng', 'Văn Thánh Miếu', 10.2427554, 105.98461119999999, 'Văn Thánh Miếu là một công trình cổ kính, mang ý nghĩa tôn vinh Nho học và các bậc hiền tài. Khuôn viên miếu có nhiều cây xanh, tạo không gian yên tĩnh, thanh bình.', 4.4, 451),
    (231, 56, 'Khu vui chơi và nghỉ dưỡng', 'Tam Đảo', 21.4559982, 105.644466, 'Tam Đảo là khu nghỉ dưỡng nổi tiếng với khí hậu mát mẻ quanh năm, tọa lạc trên dãy núi Tam Đảo. Nơi đây có nhiều điểm tham quan như Tháp Truyền Hình, Nhà Thờ Đá, và chợ đêm Tam Đảo. Du khách có thể tận hưởng cảnh đẹp núi non và ẩm thực địa phương.', NULL, 0),
    (232, 56, 'Thiên nhiên', 'Hồ Đại Lải', 21.321944444444, 105.71444444444, 'Hồ Đại Lải là một hồ nước nhân tạo rộng lớn, được bao quanh bởi rừng thông và núi đồi. Đây là điểm đến lý tưởng để tham gia các hoạt động như chèo thuyền, cắm trại, câu cá hoặc nghỉ dưỡng tại các khu resort ven hồ.', 4.4, 1071),
    (233, 56, 'Làng nghề và thủ công', 'Làng gốm Hương Canh', 21.2752712, 105.6489257, 'Làng gốm Hương Canh là một làng nghề truyền thống nổi tiếng với các sản phẩm gốm thủ công tinh xảo, đặc biệt là các sản phẩm gốm gia dụng và nghệ thuật. Du khách có thể tham quan và trải nghiệm làm gốm tại đây.', NULL, 0),
    (234, 56, 'Khu vui chơi và nghỉ dưỡng', 'Khu du lịch FLC Vĩnh Thịnh', 21.1815587, 105.489532599999, 'FLC Vĩnh Thịnh là khu nghỉ dưỡng cao cấp với không gian sang trọng, tiện nghi. Nơi đây có các dịch vụ đa dạng như bể bơi, spa, sân golf, và nhà hàng, phù hợp cho những chuyến nghỉ dưỡng cùng gia đình.', 4.1, 1286),
    (235, 56, 'Khu vui chơi và nghỉ dưỡng', 'Khu du lịch sinh thái Đầm Vạc', 21.29777778, 105.59833333, 'Đầm Vạc là một trong những đầm tự nhiên lớn nhất tại Vĩnh Phúc, có hệ sinh thái đa dạng. Du khách có thể tham gia các hoạt động như chèo thuyền, ngắm cảnh, câu cá, hoặc nghỉ ngơi tại các resort ven đầm.', 4.3, 172),
    (236, 57, 'Cảnh quan nông nghiệp', 'Ruộng bậc thang Mù Cang Chải', 21.8157529, 104.1283395, 'bậc thang Mù Cang Chải là kiệt tác thiên nhiên và lao động của đồng bào dân tộc H''Mông, nổi tiếng với vẻ đẹp hùng vĩ, đặc biệt vào mùa lúa chín (tháng 9 - tháng 10). Đây là Di sản Quốc gia và một trong những điểm đến hấp dẫn nhất Việt Nam.', 4.7, 214),
    (237, 57, 'Thiên nhiên', 'Hồ Thác Bà', 21.749029, 105.023108, 'Hồ Thác Bà là một trong những hồ nước nhân tạo lớn nhất Việt Nam, được bao quanh bởi hàng trăm hòn đảo nhỏ và cảnh quan núi non tuyệt đẹp. Du khách có thể tham gia các hoạt động như chèo thuyền, cắm trại, hoặc khám phá hang động quanh hồ.', 4.5, 266),
    (238, 57, 'Cảnh quan nông nghiệp', 'Suối Giàng', 21.6161502, 104.5930505, 'Suối Giàng nổi tiếng với những cây chè Shan tuyết cổ thụ hàng trăm năm tuổi và khí hậu mát mẻ quanh năm. Đây là nơi lý tưởng để thưởng trà, tận hưởng không khí trong lành và tìm hiểu văn hóa của đồng bào người Mông.', NULL, 0),
    (239, 57, 'Làng, bản và phố cổ', 'Bản Lìm Mông', 21.7788838, 104.2693927, 'Bản Lìm Mông là một ngôi làng nhỏ nằm giữa những ngọn núi và ruộng bậc thang tuyệt đẹp. Đây là nơi du khách có thể trải nghiệm cuộc sống của người H''Mông, tận hưởng sự yên bình và không khí trong lành.', NULL, 0),
    (240, 57, 'Thiên nhiên', 'Động Thiên Cung Suối Giàng', 21.603642699999998, 104.58601619999999, 'Hang động tại khu vực Suối Giàng, Văn Chấn, Yên Bái, có cảnh quan đá vôi và thạch nhũ. Địa danh khác với động Thiên Cung ở vịnh Hạ Long.', 4.4, 76),
    (241, 60, 'Làng, bản và phố cổ', 'Buôn Đôn', 12.8864018, 107.783268999999, 'Buôn Đôn, nằm tại tỉnh Đắk Lắk, Việt Nam, là một vùng đất nổi tiếng với văn hóa đặc sắc và khung cảnh thiên nhiên hùng vĩ. Đây là vùng đất của người dân tộc Ê-đê và Mnông, nơi bạn có thể khám phá những nét văn hóa độc đáo và các hoạt động thú vị', NULL, 0),
    (242, 60, 'Thiên nhiên', 'Hồ Lắk', 12.4225, 108.18, 'Hồ Lắk là hồ nước ngọt tự nhiên thuộc khu vực Lắk, Đắk Lắk, gắn với cảnh quan hồ, đồi núi và các buôn của cộng đồng M''nông.', 4.2, 743),
    (243, 60, 'Thiên nhiên', 'Thác Dray Nur', 12.5404255, 107.8898835, 'Thác Dray Nur, nằm ở tỉnh Đắk Lắk, là một trong những thác nước đẹp và hùng vĩ nhất của Tây Nguyên. Thác này nằm bên dòng sông Sêrêpôk, nổi tiếng với vẻ đẹp hoang sơ và huyền bí', 4.5, 8281),
    (244, 60, 'Bảo tàng', 'Bảo tàng cà phê Thế giới', 12.6908584, 108.0445203, 'Bảo tàng Thế giới Cà phê, tọa lạc tại Buôn Ma Thuột, Đắk Lắk, là một điểm đến hấp dẫn cho những ai yêu thích cà phê và muốn tìm hiểu về văn hóa cà phê toàn cầu', 4.2, 7558),
    (245, 60, 'Khu vui chơi và nghỉ dưỡng', 'Khu du lịch Ko Tam', 12.6924191, 108.1153247, 'Khu du lịch Ko Tam, tọa lạc tại Buôn Ma Thuột, Đắk Lắk, là một điểm đến sinh thái và văn hóa nổi bật của Tây Nguyên. Với diện tích khoảng 13 hecta, Ko Tam mang đến cho du khách một không gian thiên nhiên hoang sơ và yên bình, cùng với những nét văn hóa đặc sắc của người dân tộc Ê-đê', 4.4, 5121),
    (246, 61, 'Thiên nhiên', 'Công viên địa chất Đắk Nông', 12.573249299999999, 107.88762109999999, 'Công viên Địa chất Đắk Nông nổi tiếng với hệ thống hang động núi lửa độc đáo, bao gồm gần 50 hang động với tổng chiều dài hơn 10.000 mét. Công viên Địa chất Đắk Nông không chỉ là nơi bảo tồn các giá trị địa chất, mà còn là nơi lưu giữ và giới thiệu văn hóa của các dân tộc bản địa như người Mạ, người Mnông và người Ê-đê', NULL, 0),
    (247, 61, 'Thiên nhiên', 'Thác Dray Sap', 12.538567, 107.889975, 'Thác Dray Sap, còn được gọi là Thác Khói, là một trong những thác nước đẹp và hùng vĩ nhất của Tây Nguyên', 4.6, 57),
    (248, 61, 'Thiên nhiên', 'Hang động Chư Bluk', 12.4758334, 107.9449989, 'Hang động Chư Bluk, nằm ở huyện Krông Nô, tỉnh Đắk Nông, là hệ thống hang động núi lửa dài nhất Đông Nam Á. Hang động Chư Bluk nổi bật với vẻ đẹp hoang sơ và kỳ bí, với những cấu trúc đá bazan độc đáo và hệ sinh thái phong phú. Đây là điểm đến lý tưởng cho những ai yêu thích khám phá và mạo hiểm, bởi việc tiếp cận hang động không hề dễ dàng và đòi hỏi sự hướng dẫn của người dân địa phương', 4.7, 161),
    (249, 61, 'Thiên nhiên', 'Hồ Ea Snô', 12.438377899999999, 107.9124468, 'Hồ Ea Snô được bao quanh bởi hệ sinh thái thực vật đa dạng và phong phú, là nơi sinh sống của nhiều cộng đồng dân tộc bản địa. Khung cảnh nơi đây mang lại cảm giác bình yên và thư thá', 4.3, 15),
    (250, 61, 'Thiên nhiên', 'Khu bảo tồn thiên nhiên Nâm Nung', 12.2545890999999, 107.8109944, 'Khu bảo tồn nằm ở tỉnh Đắk Nông, nổi tiếng với hệ sinh thái đa dạng gồm rừng nguyên sinh, thác nước hùng vĩ và nhiều loài động thực vật quý hiếm. Đây là địa điểm lý tưởng cho các hoạt động khám phá thiên nhiên, trekking, và nghiên cứu sinh thái.', 4.1, 647),
    (251, 58, 'Di tích lịch sử', 'Đồi A1', 21.3829319, 103.017673, 'Đồi A1 là một trong những di tích lịch sử quan trọng trong chiến dịch Điện Biên Phủ, nơi từng diễn ra các trận đánh khốc liệt. Hiện nay, nơi đây trở thành điểm tham quan với hầm chiến đấu, hệ thống giao thông hào và bảo tồn nhiều hiện vật lịch sử.', 4.5, 2836),
    (252, 58, 'Di tích lịch sử', 'Hầm De Castries', 21.384944, 103.0106749, 'Đây là nơi ở và chỉ huy của tướng De Castries trong chiến dịch Điện Biên Phủ. Hầm được xây dựng kiên cố và hiện nay là di tích lịch sử được bảo tồn để tái hiện lại chiến trường năm xưa.', 4.3, 2559),
    (253, 58, 'Bảo tàng', 'Bảo tàng chiến thắng Điện Biên Phủ', 21.3807568999999, 103.0152583, 'Bảo tàng lưu giữ các hiện vật, tư liệu và hình ảnh về chiến dịch Điện Biên Phủ, tái hiện lịch sử hào hùng của dân tộc Việt Nam. Đây là điểm đến không thể bỏ qua khi ghé thăm Điện Biên.', 4.7, 1271),
    (254, 58, 'Cảnh quan nông nghiệp', 'Cánh đồng Mường Thanh', 21.36596694, 103.00868389, 'Cánh đồng lúa lớn nhất vùng Tây Bắc, nổi tiếng với vẻ đẹp thơ mộng và vai trò quan trọng trong lịch sử chiến dịch Điện Biên Phủ. Cảnh quan ở đây thay đổi theo mùa vụ, thu hút nhiều du khách đến chiêm ngưỡng.', 4.7, 104),
    (255, 58, 'Di tích lịch sử', 'Tượng đài chiến thắng Điện Biên Phủ', 21.3921742, 103.0189383, 'Tượng đài nằm trên đồi D1, là biểu tượng của chiến thắng lịch sử Điện Biên Phủ. Đây là nơi tôn vinh sự hy sinh và chiến công của các chiến sĩ Việt Nam, đồng thời cũng là điểm ngắm toàn cảnh thành phố Điện Biên.', 4.6, 1393),
    (256, 62, 'Thiên nhiên', 'Vườn quốc gia Cát Tiên', 11.347222222222, 107.15138888889, 'Một trong những vườn quốc gia nổi tiếng nhất Việt Nam, nằm ở tỉnh Đồng Nai. Nơi đây sở hữu hệ sinh thái phong phú với nhiều loài động thực vật quý hiếm, cùng các hoạt động như khám phá rừng, ngắm chim và dã ngoại.', 4.7, 1716),
    (257, 62, 'Khu vui chơi và nghỉ dưỡng', 'Khu du lịch Bửu Long', 10.9629837, 106.7936911, 'Được ví như “Vịnh Hạ Long thu nhỏ” ở Đồng Nai, Bửu Long nổi bật với hồ nước trong xanh, núi đá và cảnh quan thơ mộng. Đây là nơi lý tưởng cho các hoạt động dã ngoại, cắm trại và chụp ảnh.', 4.2, 11157),
    (258, 62, 'Thiên nhiên', 'Hồ Trị An', 11.13139, 107.13444, 'Hồ Trị An với trên 70 đảo lớn, nhỏ và nhiều đảo trong số này có cư dân sinh sống, cộng thêm vài hòn đảo có diện tích lớn được khai thác du lịch gần chục năm trở lại đây đã trở thành điểm nhấn của sông nước Trị An', 4.5, 1545),
    (259, 62, 'Thiên nhiên', 'Đảo Ó', 11.1080756, 107.1020779, 'Một hòn đảo nằm giữa lòng hồ Trị An, sở hữu không gian xanh mát và trong lành. Đảo Ó là điểm đến hấp dẫn cho các hoạt động dã ngoại, cắm trại, và thưởng ngoạn thiên nhiên.', 4, 345),
    (260, 62, 'Thiên nhiên', 'Thác Giang Điền', 10.921673, 106.983357, 'Một thác nước đẹp ở Đồng Nai, được bao quanh bởi rừng cây xanh mát. Thác Giang Điền là địa điểm du lịch sinh thái, hấp dẫn cho các hoạt động nghỉ dưỡng, picnic và chụp ảnh kỷ niệm.', 4.4, 2692),
    (261, 63, 'Thiên nhiên', 'Vườn quốc gia Tràm Chim', 10.725, 105.517, 'Vườn quốc gia ở Đồng Tháp, nơi bảo tồn hệ sinh thái đất ngập nước đặc trưng Đồng bằng sông Cửu Long. Tràm Chim là nhà của nhiều loài chim quý hiếm, đặc biệt là sếu đầu đỏ.', 4.1, 3521),
    (262, 63, 'Cảnh quan nông nghiệp', 'Làng hoa Sa Đéc', 10.3153547, 105.7499572, 'Làng nghề truyền thống nổi tiếng ở Đồng Tháp, nơi trồng hàng trăm loài hoa đẹp và quý. Làng hoa thu hút du khách với những vườn hoa rực rỡ quanh năm.', 4.4, 4091),
    (263, 63, 'Di tích lịch sử', 'Khu di tích Xẻo Quýt', 10.399444, 105.801667, 'Một khu di tích lịch sử kết hợp du lịch sinh thái tại Đồng Tháp, nơi tái hiện các căn cứ cách mạng trong rừng tràm thời kháng chiến.', 4.5, 948),
    (264, 63, 'Di tích lịch sử', 'Lăng cụ Nguyễn Sinh Sắc', 10.4466512, 105.6310592, 'Nơi an nghỉ của cụ Nguyễn Sinh Sắc, thân sinh Chủ tịch Hồ Chí Minh. Lăng được thiết kế hài hòa giữa kiến trúc và cảnh quan thiên nhiên.', 4.7, 925),
    (265, 63, 'Chợ', 'Chợ Cao Lãnh', 10.4546627, 105.637196899999, 'Một khu chợ sầm uất tại thành phố Cao Lãnh, nơi du khách có thể khám phá văn hóa ẩm thực và đời sống người dân địa phương.', 4.3, 2211),
    (266, 15, 'Thiên nhiên', 'Biển Hồ (T''Nưng)', 14.0453573, 107.9980662, 'Biển Hồ, còn gọi là hồ T''Nưng, là hồ nước ngọt tự nhiên ở khu vực Pleiku, Gia Lai, hình thành trên địa hình núi lửa cổ và nổi bật với cảnh quan mặt nước giữa đồi núi.', 4.4, 660),
    (267, 15, 'Thiên nhiên', 'Thác Phú Cường', 13.662655, 108.135356, 'Một thác nước đẹp tại Gia Lai, nằm giữa rừng nguyên sinh. Thác nổi bật với dòng nước trắng xóa, đổ từ độ cao hơn 45m.', 4.1, 359),
    (268, 15, 'Tôn giáo và tín ngưỡng', 'Chùa Minh Thành', 13.9662578, 108.0063563, 'Ngôi chùa nổi tiếng ở Gia Lai, được xây dựng theo phong cách Phật giáo Nhật Bản, với kiến trúc độc đáo và không gian thanh tịnh.', 4.7, 3436),
    (269, 15, 'Công trình và không gian xây dựng', 'Quảng trường Đại Đoàn Kết', 13.983124499999999, 108.00577679999999, 'Quảng trường lớn nhất Tây Nguyên, nằm tại Pleiku, Gia Lai. Đây là nơi tổ chức các sự kiện lớn và cũng là biểu tượng của đoàn kết dân tộc.', 4.8, 749),
    (270, 15, 'Cảnh quan nông nghiệp', 'Đồi chè Bàu Cạn', 13.8403863, 107.9352311, 'Đồi chè Bàu Cạn ở Gia Lai là một trong những đồi chè lâu đời nhất Việt Nam, nổi bật với những luống chè xanh mướt trải dài, mang vẻ đẹp yên bình. Đây là điểm đến lý tưởng để thư giãn và chụp ảnh giữa không gian thiên nhiên tươi mát.', NULL, 0),
    (271, 16, 'Công trình và không gian xây dựng', 'Cột cờ Lũng Cú', 23.36794444, 105.31563333, 'Cột cờ Lũng Cú, nằm ở cực Bắc Việt Nam (Hà Giang), là biểu tượng thiêng liêng của chủ quyền quốc gia. Du khách chinh phục gần 800 bậc thang để chiêm ngưỡng lá cờ đỏ sao vàng tung bay trên đỉnh núi hùng vĩ.', 4.6, 9276),
    (272, 16, 'Thiên nhiên', 'Đèo Mã Pí Lèng', 23.240808, 105.410942, 'Đèo Mã Pí Lèng là cung đường hùng vĩ tại Hà Giang, với sông Nho Quế xanh ngọc chảy uốn lượn phía dưới. Đây là điểm thu hút phượt thủ và du khách yêu vẻ đẹp thiên nhiên hoang sơ.', 4.8, 812),
    (273, 16, 'Làng, bản và phố cổ', 'Phố cổ Đồng Văn', 23.28177778, 105.35989444, 'Phố cổ Đồng Văn (Hà Giang) lưu giữ nét kiến trúc cổ kính với những ngôi nhà tường đất, mái ngói âm dương. Phiên chợ cuối tuần nhộn nhịp là điểm nhấn văn hóa hấp dẫn.', 4.6, 3175),
    (274, 16, 'Thiên nhiên', 'Hẻm Tu Sản', 23.228399, 105.424618, 'Hẻm Tu Sản, nơi sâu nhất Đông Nam Á, nổi bật với vách đá cao 800m và dòng sông Nho Quế xanh biếc. Du khách có thể chèo thuyền khám phá khung cảnh kỳ vĩ này.', 5, 11),
    (275, 16, 'Di tích lịch sử', 'Dinh Vua Mèo', 23.256492, 105.262146, 'Dinh Vua Mèo (Hà Giang) là dinh thự cổ của dòng họ Vương, với kiến trúc kết hợp độc đáo giữa Trung Hoa, Pháp và văn hóa dân tộc H''Mông, thu hút nhiều du khách tham quan.', 4.6, 181),
    (276, 17, 'Tôn giáo và tín ngưỡng', 'Chùa Tam Chúc', 20.5532427, 105.7961457, 'Chùa Tam Chúc (Hà Nam) là một trong những quần thể chùa lớn nhất Việt Nam, nổi bật với kiến trúc hoành tráng và cảnh quan thiên nhiên tươi đẹp. Được bao quanh bởi những dãy núi, hồ nước trong xanh, đây là nơi thu hút tín đồ Phật giáo và du khách tham quan.', 4.4, 358),
    (277, 17, 'Tôn giáo và tín ngưỡng', 'Đền Trần Thương', 20.5761573, 106.1037476, 'Đền Trần Thương (Hà Nam) thờ các vị vua Trần, nổi bật với kiến trúc cổ kính và không gian thanh tịnh. Đền là điểm đến văn hóa, tâm linh, thu hút du khách vào mùa lễ hội.', 4.7, 531),
    (278, 17, 'Thiên nhiên', 'Hang Luồn – Ao Dong (Hà Nam)', 20.5403125, 105.8576406, 'Hang Luồn trong khu Ao Dong, khu vực Liên Sơn, Kim Bảng, Hà Nam, là hang xuyên thủy giữa cảnh quan núi đá vôi và mặt nước.', 4.1, 89),
    (279, 17, 'Tôn giáo và tín ngưỡng', 'Đền Lảnh Giang', 20.6689599, 106.0253848, 'Đền Lảnh Giang tại khu vực Mộc Nam, Duy Tiên, Hà Nam, là di tích tín ngưỡng thờ các vị thủy thần gắn với truyền thuyết thời Hùng Vương.', 4.7, 886),
    (280, 17, 'Làng, bản và phố cổ', 'Làng Vũ Đại', 20.482340999999998, 106.16657269999999, 'Làng Vũ Đại (Hà Nam) nổi tiếng nhờ sự gắn kết với tác phẩm "Chí Phèo" của nhà văn Nam Cao. Nơi đây có những ngôi nhà cổ, là điểm du lịch văn hóa, nơi lưu giữ nét đẹp văn hóa truyền thống.', NULL, 0),
    (281, 18, 'Di tích lịch sử', 'Lăng Chủ tịch Hồ Chí Minh', 21.03666667, 105.83472222, 'Lăng Chủ tịch Hồ Chí Minh (Hà Nội) là nơi lưu giữ thi hài của Chủ tịch Hồ Chí Minh, trở thành biểu tượng của lòng tôn kính và biết ơn của nhân dân Việt Nam.', 4.5, 21480),
    (282, 18, 'Thiên nhiên', 'Hồ Gươm', 21.028888888889, 105.8525, 'Hồ Gươm (Hà Nội) là trung tâm của thủ đô, nổi bật với Tháp Rùa và cầu Thê Húc. Đây là điểm du lịch hấp dẫn, nơi người dân thư giãn và là biểu tượng của Hà Nội.', 4.7, 13004),
    (283, 18, 'Di tích lịch sử', 'Văn Miếu - Quốc Tử Giám', 21.028611, 105.835556, 'Văn Miếu - Quốc Tử Giám (Hà Nội) là một di tích lịch sử và văn hóa, nơi thờ Khổng Tử và là trường đại học đầu tiên của Việt Nam. Đây là điểm tham quan giáo dục và văn hóa.', 4.6, 25999),
    (284, 18, 'Di tích lịch sử', 'Hoàng thành Thăng Long', 21.0325, 105.83972, 'Hoàng Thành Thăng Long (Hà Nội) là di tích lịch sử quan trọng của Việt Nam, từng là trung tâm quyền lực của nhiều triều đại. Di tích này mang đậm dấu ấn lịch sử và văn hóa dân tộc.', 4.4, 19575),
    (285, 18, 'Công trình và không gian xây dựng', 'Cầu Long Biên', 21.043333333333, 105.85888888889, 'Cầu Long Biên (Hà Nội) là một trong những cây cầu lâu đời nhất, mang đậm giá trị lịch sử. Cầu nối liền hai bờ sông Hồng và là biểu tượng của thủ đô.', 4.6, 114),
    (286, 19, 'Di tích lịch sử', 'Ngã ba Đồng Lộc', 18.3995633999999, 105.738784599999, 'Ngã ba Đồng Lộc (Hà Tĩnh) là di tích lịch sử nổi tiếng gắn liền với cuộc kháng chiến chống Mỹ. Nơi đây là nơi tưởng niệm các liệt sĩ hy sinh trong chiến tranh.', 4.7, 1538),
    (287, 19, 'Tôn giáo và tín ngưỡng', 'Chùa Hương Tích (Hà Tĩnh)', 18.5341424999999, 105.789192, 'Chùa Hương Tích nằm trên dãy Hồng Lĩnh, khu vực Thiên Lộc, Can Lộc, Hà Tĩnh. Đây là di tích Phật giáo và điểm hành hương gắn với cảnh quan núi rừng.', 4.6, 1287),
    (288, 19, 'Thiên nhiên', 'Biển Thiên Cầm', 18.273540699999998, 106.1042518, 'Biển Thiên Cầm (Hà Tĩnh) là bãi biển xinh đẹp với bãi cát dài và nước biển trong xanh, nơi du khách có thể thư giãn và tham gia các hoạt động thể thao biển.', 4.3, 1070),
    (289, 19, 'Di tích lịch sử', 'Khu di tích Nguyễn Du', 18.6649985, 105.7668101, 'Khu di tích Nguyễn Du (Hà Tĩnh) là nơi tưởng niệm đại thi hào Nguyễn Du, tác giả của "Truyện Kiều". Di tích này giữ gìn những giá trị văn hóa, lịch sử về cuộc đời và sự nghiệp của ông.', 4.7, 646),
    (290, 19, 'Thiên nhiên', 'Đèo Ngang', 17.956111111111, 106.46777777778, 'Đèo Ngang (Quảng Bình) là một trong những con đèo đẹp nhất Việt Nam, nối liền hai tỉnh Quảng Bình và Hà Tĩnh. Đèo có cảnh quan hùng vĩ và thơ mộng.', 4.4, 372),
    (291, 22, 'Thiên nhiên', 'Đảo Cò Chi Lăng Nam', 20.7136101999999, 106.2279224, 'Đảo Cò Chi Lăng Nam (Hải Dương) là một khu vực bảo tồn thiên nhiên nổi bật với hàng nghìn con cò sinh sống. Đây là địa điểm du lịch sinh thái lý tưởng, với không gian yên bình và cảnh quan tuyệt đẹp.', 4.3, 336),
    (292, 22, 'Tôn giáo và tín ngưỡng', 'Chùa Côn Sơn', 21.149837, 106.384008, 'Chùa Côn Sơn (Hải Dương) là di tích lịch sử và văn hóa, nổi bật với kiến trúc cổ kính và không gian thanh tịnh. Nơi đây là một trong những địa điểm du lịch tâm linh nổi tiếng ở miền Bắc.', 4.7, 704),
    (293, 22, 'Làng, bản và phố cổ', 'Làng rối nước Thanh Hải', 20.8877436, 106.4015854, 'Làng rối nước Thanh Hải (Hải Dương) là nơi bảo tồn và phát triển nghệ thuật rối nước truyền thống. Du khách có thể thưởng thức những màn rối đặc sắc trong không gian văn hóa dân gian đậm đà.', 4.6, 142),
    (294, 22, 'Tôn giáo và tín ngưỡng', 'Đền Kiếp Bạc', 21.1510532, 106.3275892, 'Đền Kiếp Bạc (Hải Dương) là nơi thờ Hưng Đạo Đại Vương Trần Quốc Tuấn, người có công lớn trong chiến tranh chống Nguyên. Đền mang đậm giá trị lịch sử và văn hóa.', 4.6, 3120),
    (295, 22, 'Chợ', 'Chợ Đông Ngô Quyền', 20.9335897, 106.3061075, 'Chợ Đông Ngô Quyền là chợ tại khu vực thành phố Hải Dương theo địa giới cũ, phục vụ giao thương và nhu cầu mua sắm của người dân địa phương.', 3.0, 1),
    (296, 23, 'Thiên nhiên', 'Đồ Sơn', 20.6872771, 106.7954793, 'Đồ Sơn (Hải Phòng) là một bãi biển đẹp nổi tiếng với những dãy núi và biển xanh. Đây là khu du lịch biển với các hoạt động thể thao nước và thư giãn dưới ánh nắng.', NULL, 0),
    (297, 23, 'Thiên nhiên', 'Cát Bà', 20.8, 106.99972199999999, 'Cát Bà (Hải Phòng) là hòn đảo nổi tiếng với bãi biển tuyệt đẹp và hệ sinh thái đa dạng. Nơi đây là một điểm đến lý tưởng cho những ai yêu thích du lịch sinh thái và biển.', 4.4, 1372),
    (298, 23, 'Di tích lịch sử', 'Bến K15 (Đồ Sơn)', 20.6773637, 106.80293209999999, 'Bến K15 tại Đồ Sơn, Hải Phòng, là di tích gắn với các chuyến tàu không số và tuyến vận tải Hồ Chí Minh trên biển. Bến Nghiêng là một di tích khác ở gần đó.', 4.7, 112),
    (299, 23, 'Công trình và không gian xây dựng', 'Hải đăng Hòn Dấu', 20.6664244, 106.8163921, 'Hải đăng Hòn Dấu (Hải Phòng) là ngọn hải đăng cổ kính, nằm trên đảo Hòn Dấu. Đây là một trong những ngọn hải đăng quan trọng ở khu vực vịnh Bắc Bộ.', NULL, 0),
    (300, 23, 'Công trình và không gian xây dựng', 'Cầu Hoàng Văn Thụ', 20.867265, 106.681336, 'Cầu Hoàng Văn Thụ (Hải Phòng) là một cây cầu huyết mạch nối liền các khu vực trong thành phố. Cầu nổi bật với kiến trúc hiện đại và là điểm đến tham quan chính của du khách.', 4.8, 193),
    (301, 24, 'Thiên nhiên', 'Khu du lịch Lung Ngọc Hoàng', 9.72275, 105.69991667, 'Khu du lịch Lung Ngọc Hoàng (Hậu Giang) là khu bảo tồn thiên nhiên nổi bật với hệ sinh thái rừng ngập mặn. Đây là điểm đến lý tưởng cho những ai yêu thích du lịch sinh thái và nghiên cứu động thực vật.', 5, 1),
    (302, 24, 'Chợ', 'Chợ nổi Ngã Bảy', 9.8146443, 105.824952099999, 'Chợ nổi Ngã Bảy (Hậu Giang) là một trong những chợ nổi nổi tiếng ở miền Tây. Du khách có thể trải nghiệm việc mua bán trên sông và khám phá nền văn hóa chợ nổi đặc sắc.', 4.3, 137),
    (303, 24, 'Khu vui chơi và nghỉ dưỡng', 'Công viên giải trí Ti & Ni (Kittyd & Minnied)', 9.9586812, 105.7348123, 'Công viên giải trí trong khuôn viên Đại học Võ Trường Toản, khu vực Tân Phú Thạnh, Châu Thành A, Hậu Giang, có các khu vui chơi và công viên nước.', 3.3, 117),
    (305, 24, 'Thiên nhiên', 'Sông Cái Lớn', 9.9236111111111, 105.09305555556, 'Sông Cái Lớn là tuyến sông thuộc vùng Tây Nam Bộ, liên quan đến khu vực Hậu Giang và Kiên Giang theo địa giới gốc của dataset. Dòng sông gắn với cảnh quan sông nước và sinh hoạt ven sông.', 4.3, 479),
    (306, 20, 'Thiên nhiên', 'Thung Nai', 20.72911497, 105.3135047, 'Thung Nai (Hòa Bình) là khu du lịch nổi tiếng với cảnh sắc thiên nhiên hùng vĩ, bao gồm hồ nước rộng lớn và các dãy núi bao quanh. Nơi đây là địa điểm lý tưởng cho du khách yêu thích du lịch sinh thái và tham gia các hoạt động ngoài trời như chèo thuyền.', NULL, 0),
    (307, 20, 'Làng, bản và phố cổ', 'Mai Châu', 20.664779, 105.0833255, 'Mai Châu (Hòa Bình) là một thung lũng xinh đẹp, nổi tiếng với những ngôi nhà sàn và cảnh sắc thiên nhiên hoang sơ. Mai Châu thu hút du khách bởi không khí trong lành, cộng với nền văn hóa đặc sắc của đồng bào dân tộc Thái.', NULL, 0),
    (308, 20, 'Thiên nhiên', 'Động Đá Bạc', 20.8224436999999, 105.6051945, 'Động Đá Bạc là hang động đá vôi tại khu vực Lương Sơn, Hòa Bình, có các khối thạch nhũ và cảnh quan hang tự nhiên.', 4.7, 70),
    (309, 20, 'Thiên nhiên', 'Cửu thác Tú Sơn', 20.7092011, 105.4170941, 'Cửu thác Tú Sơn là khu cảnh quan thác, suối và rừng tại khu vực Tú Sơn, Kim Bôi, Hòa Bình, gắn với không gian văn hóa Mường.', 3.6, 334),
    (310, 20, 'Tôn giáo và tín ngưỡng', 'Đền Thác Bờ', 20.7682656, 105.1758246, 'Đền Thác Bờ (Hòa Bình) là một di tích lịch sử, thờ nữ tướng Cao Thị Lịch. Đền nằm gần thác Bờ, có khung cảnh huyền bí và là nơi linh thiêng, thu hút du khách đến tham quan và cầu nguyện.', 4.5, 1071),
    (311, 21, 'Làng, bản và phố cổ', 'Phố Hiến', 20.65973387, 106.06353225, 'Phố Hiến (Hưng Yên) là một khu phố cổ nổi tiếng với những công trình kiến trúc mang đậm dấu ấn lịch sử. Đây là một điểm đến hấp dẫn cho du khách muốn tìm hiểu về lịch sử, văn hóa và thưởng thức ẩm thực địa phương.', NULL, 0),
    (312, 21, 'Tôn giáo và tín ngưỡng', 'Chùa Chuông', 20.6558, 106.05, 'Chùa Chuông là ngôi chùa thuộc quần thể di tích Phố Hiến ở Hưng Yên, gắn với kiến trúc Phật giáo và sinh hoạt tín ngưỡng của địa phương.', 4.7, 1226),
    (313, 21, 'Làng nghề và thủ công', 'Làng nghề đúc đồng Lộng Thượng', 20.9923582, 106.0628857, 'Làng nghề đúc đồng Lộng Thượng tại khu vực Đại Đồng, Văn Lâm, Hưng Yên, nổi tiếng với đồ thờ cúng và các sản phẩm đồng thủ công.', NULL, 0),
    (314, 21, 'Tôn giáo và tín ngưỡng', 'Đền Phù Ủng', 20.8847818, 106.143607899999, 'Đền Phù Ủng (Hưng Yên) là di tích lịch sử, thờ Đức thánh Phù Ủng, người có công giúp vua Hùng trong các cuộc chiến. Đền nằm trong khuôn viên rộng lớn, với không gian thanh tịnh và linh thiêng.', 4.6, 145),
    (315, 21, 'Tôn giáo và tín ngưỡng', 'Đình làng Nôm', 20.9928035, 106.0812014, 'Đình làng Nôm (Hưng Yên) là một di tích văn hóa đặc sắc, nổi bật với kiến trúc cổ truyền và các hoạt động lễ hội dân gian. Đây là điểm đến thu hút du khách khám phá những giá trị văn hóa truyền thống.', 4.7, 53)
) AS v(place_id, region_id, place_type_name, name, latitude, longitude,
       introduction, rating, rating_count)
JOIN public.place_type AS t ON t.name = v.place_type_name;

