JOIN public.recommendation_criterion AS c ON c.code = v.criterion_code;

INSERT INTO public.recommendation_weight
    (recommendation_config_id, criterion_id, weight_value)
SELECT 1, c.criterion_id, v.weight_value
FROM (VALUES
    ('PREFERENCE', 0.4),
    ('CLUSTER', 0.2),
    ('ACTIVITY', 0.2),
    ('RATING', 0.1),
    ('POPULARITY', 0.1)
) AS v(criterion_code, weight_value)
JOIN public.recommendation_criterion AS c ON c.code = v.criterion_code;

DO $check$
BEGIN
    IF (SELECT count(*) FROM public.region) <> 63
       OR (SELECT count(*) FROM public.place) <> 311
       OR (SELECT count(*) FROM public.recommendation_config) <> 1
       OR (SELECT count(*) FROM public.recommendation_weight) <> 5
       OR (SELECT count(*) FROM public.place_feature) <> 311
       OR (SELECT count(*) FROM public.place_feature_value) <> 10885 THEN
        RAISE EXCEPTION 'Post-import row-count check failed; transaction rolled back';
    END IF;
    IF (SELECT count(*) FROM public.place_feature_value pfv
        JOIN public.recommendation_criterion rc ON rc.criterion_id = pfv.criterion_id
        WHERE LEFT(rc.code, 6) = 'kind__' AND pfv.feature_value = 1) <> 345 THEN
        RAISE EXCEPTION 'Place-type feature-link check failed; transaction rolled back';
    END IF;
END
$check$;

-- Explicit IDs require identity generators to resume after the imported rows.
ALTER TABLE public.region ALTER COLUMN region_id RESTART WITH 64;
ALTER TABLE public.place ALTER COLUMN place_id RESTART WITH 316;
ALTER TABLE public.recommendation_config ALTER COLUMN recommendation_config_id RESTART WITH 2;
ALTER TABLE public.place_feature ALTER COLUMN place_feature_id RESTART WITH 316;

COMMIT;
